// ═══════════════════════════════════════════════════════════════════════════════
//  GRAPH SYSTEM
// ═══════════════════════════════════════════════════════════════════════════════

function mkC(x1, x2, y1, y2, W = 254, H = 158) {
  return {
    W, H, x1, x2, y1, y2,
    sx: x => ((x - x1) / (x2 - x1)) * W,
    sy: y => H - ((y - y1) / (y2 - y1)) * H,
  };
}

function mkPath(fn, c, steps = 90) {
  const { x1, x2, y1, y2, sx, sy } = c;
  let d = "", up = true;
  for (let i = 0; i <= steps; i++) {
    const x = x1 + (x2 - x1) * i / steps;
    const y = fn(x);
    const ok = isFinite(y) && y >= y1 - 0.5 && y <= y2 + 0.5;
    if (ok) {
      const px = sx(x).toFixed(1);
      const py = sy(Math.min(y2 + 0.4, Math.max(y1 - 0.4, y))).toFixed(1);
      d += up ? `M${px},${py}` : ` L${px},${py}`;
      up = false;
    } else { up = true; }
  }
  return d;
}

// Filled region between curve and x-axis
function mkShade(fn, x1, x2, c, steps = 60) {
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const x = x1 + (x2 - x1) * i / steps;
    const y = Math.max(c.y1, Math.min(c.y2, fn(x)));
    pts.push(`${c.sx(x).toFixed(1)},${c.sy(y).toFixed(1)}`);
  }
  const oy = c.sy(0).toFixed(1);
  return `M${pts[0]} ${pts.slice(1).map(p => `L${p}`).join(' ')} L${c.sx(x2).toFixed(1)},${oy} L${c.sx(x1).toFixed(1)},${oy} Z`;
}

// Axes + grid
function Axes({ c }) {
  const { W, H, x1, x2, y1, y2, sx, sy } = c;
  const ox = sx(0), oy = sy(0);
  const xs = [], ys = [];
  for (let x = Math.ceil(x1); x <= Math.floor(x2); x++) xs.push(x);
  for (let y = Math.ceil(y1); y <= Math.floor(y2); y++) ys.push(y);
  const range = (v, max) => Math.abs(v) <= max && v !== 0;
  const xSpan = x2 - x1, ySpan = y2 - y1;
  const xStep = xSpan > 8 ? 2 : 1;
  const yStep = ySpan > 8 ? 2 : 1;
  return (<>
    {xs.map(x => <line key={`gx${x}`} x1={sx(x)} y1={0} x2={sx(x)} y2={H} stroke="#E8EDF3" strokeWidth={0.5} />)}
    {ys.map(y => <line key={`gy${y}`} x1={0} y1={sy(y)} x2={W} y2={sy(y)} stroke="#E8EDF3" strokeWidth={0.5} />)}
    <line x1={2} y1={oy} x2={W - 5} y2={oy} stroke="#475569" strokeWidth={1.5} />
    <line x1={ox} y1={H - 2} x2={ox} y2={4} stroke="#475569" strokeWidth={1.5} />
    <polygon points={`${W},${oy} ${W-7},${oy-3} ${W-7},${oy+3}`} fill="#475569" />
    <polygon points={`${ox},0 ${ox-3},7 ${ox+3},7`} fill="#475569" />
    {xs.map(x => (<g key={`tx${x}`}>
      <line x1={sx(x)} y1={oy - 3} x2={sx(x)} y2={oy + 3} stroke="#475569" strokeWidth={1} />
      {x !== 0 && Math.abs(x) % xStep === 0 && range(x, 12) && (
        <text x={sx(x)} y={oy + 12} textAnchor="middle" fontSize="8" fill="#64748B" fontFamily="DM Sans">{x}</text>
      )}
    </g>))}
    {ys.map(y => (<g key={`ty${y}`}>
      <line x1={ox - 3} y1={sy(y)} x2={ox + 3} y2={sy(y)} stroke="#475569" strokeWidth={1} />
      {y !== 0 && Math.abs(y) % yStep === 0 && range(y, 12) && (
        <text x={ox - 5} y={sy(y) + 3} textAnchor="end" fontSize="8" fill="#64748B" fontFamily="DM Sans">{y}</text>
      )}
    </g>))}
    <text x={ox + 3} y={oy + 12} textAnchor="start" fontSize="8" fill="#64748B" fontFamily="DM Sans">O</text>
    <text x={W - 2} y={oy - 4} textAnchor="end" fontSize="9" fill="#94A3B8" fontFamily="DM Sans" fontStyle="italic">x</text>
    <text x={ox + 4} y={10} textAnchor="start" fontSize="9" fill="#94A3B8" fontFamily="DM Sans" fontStyle="italic">y</text>
  </>);
}

// Main graph renderer — preExtras renders BEHIND axes (e.g. shading)
function Graph({ spec }) {
  const {
    fn, fn2, xr = [-5, 5], yr = [-4, 4],
    color = "#2563EB", color2 = "#9333EA",
    label = "f", extras, preExtras,
  } = spec;
  const c = mkC(xr[0], xr[1], yr[0], yr[1]);
  const { W, H, sx, sy } = c;
  const lx = xr[1] - (xr[1] - xr[0]) * 0.09;
  const ly = fn(lx);
  const lOk = isFinite(ly) && ly >= yr[0] && ly <= yr[1];
  return (
    <svg viewBox={`0 0 ${W} ${H}`}
      style={{ width: "100%", maxHeight: 160, display: "block", background: "#FAFCFF", borderRadius: 8, border: "1px solid #E2E8F0" }}>
      {/* BACKGROUND layer: shading */}
      {preExtras && preExtras(c)}
      <Axes c={c} />
      <path d={mkPath(fn, c)} stroke={color} strokeWidth={2.2} fill="none" strokeLinecap="round" strokeLinejoin="round" />
      {fn2 && <path d={mkPath(fn2, c)} stroke={color2} strokeWidth={1.8} fill="none" strokeDasharray="6,3" />}
      {lOk && <text x={sx(lx) + 5} y={sy(ly) - 4} fontSize="10" fill={color} fontFamily="DM Sans" fontStyle="italic" fontWeight="bold">{label}</text>}
      {/* FOREGROUND layer: dots, labels */}
      {extras && extras(c)}
    </svg>
  );
}

// ── SVG helper primitives ─────────────────────────────────────────────────────
const gPt  = (x, y, c, col = "#EF4444") =>
  <circle key={`pt${x}${y}`} cx={c.sx(x)} cy={c.sy(y)} r={3.5} fill={col} stroke="#fff" strokeWidth={1} />;

const gDV  = (x, c, col = "#F59E0B") =>
  <line key={`dv${x}`} x1={c.sx(x)} y1={0} x2={c.sx(x)} y2={c.H} stroke={col} strokeWidth={1.2} strokeDasharray="5,3" />;

const gDH  = (y, c, col = "#F59E0B") =>
  <line key={`dh${y}`} x1={0} y1={c.sy(y)} x2={c.W} y2={c.sy(y)} stroke={col} strokeWidth={1.2} strokeDasharray="5,3" />;

const gTan = (fn, a, m, c, col = "#EF4444") =>
  <path key={`tan${a}`} d={mkPath(x => m * (x - a) + fn(a), c)} stroke={col} strokeWidth={1.8} fill="none" strokeDasharray="6,3" />;

// Shaded region between curve and x-axis
const gShade = (fn, x1, x2, c, col) =>
  <path key={`sh${x1}${x2}${col}`} d={mkShade(fn, x1, x2, c)} fill={col} stroke="none" />;

// Sign label (+ or −) placed at a position
const gSign = (x, y, sign, c, col) =>
  <text key={`sg${x}${y}`} x={c.sx(x)} y={c.sy(y)} textAnchor="middle" fontSize="13" fill={col} fontWeight="bold" fontFamily="DM Sans">{sign}</text>;

// Annotation label near a point
const gNote = (x, y, txt, c, col = "#374151") =>
  <text key={`nt${x}${y}`} x={c.sx(x) + 5} y={c.sy(y) - 5} fontSize="8.5" fill={col} fontFamily="DM Sans" fontWeight="600">{txt}</text>;

// Trend arrow (increase/decrease indicator) at a point on the curve
const gTrend = (fn, x, inc, c) => {
  const px = c.sx(x), py = c.sy(fn(x));
  const col = inc ? "#10B981" : "#EF4444";
  const pts = inc
    ? `${px - 5},${py + 4} ${px},${py - 4} ${px + 5},${py + 4}`
    : `${px - 5},${py - 4} ${px},${py + 4} ${px + 5},${py - 4}`;
  return <polygon key={`tr${x}`} points={pts} fill={col} opacity={0.75} />;
};

// Color constants
const C_POS = "rgba(16,185,129,0.15)";
const C_NEG = "rgba(239,68,68,0.13)";
const C_MAX = "#10B981";
const C_MIN = "#EF4444";

// ═══════════════════════════════════════════════════════════════════════════════
//  DRAG GRAPH — interactive inequality solver
// ═══════════════════════════════════════════════════════════════════════════════

// Numerical root-finder: find x where fn(x) = k
function findRoots(fn, k, xr, steps = 600) {
  const [x0, x1] = xr;
  const dx = (x1 - x0) / steps;
  const roots = [];
  let prev = fn(x0) - k;
  for (let i = 1; i <= steps; i++) {
    const x = x0 + i * dx;
    const curr = fn(x) - k;
    if (prev * curr < 0) {
      let lo = x - dx, hi = x;
      for (let j = 0; j < 24; j++) {
        const mid = (lo + hi) / 2;
        if ((fn(lo) - k) * (fn(mid) - k) < 0) hi = mid; else lo = mid;
      }
      const r = (lo + hi) / 2;
      if (roots.length === 0 || Math.abs(r - roots[roots.length - 1]) > 0.05)
        roots.push(r);
    }
    prev = curr;
  }
  return roots;
}

// Format x value for display on axis
const fmtX = x => {
  const r = Math.round(x * 10) / 10;
  return r === 0 ? "0" : String(r);
};

// Shade path above/below the dragged line
function mkDragShade(fn, k, type, xr, c, steps = 150) {
  const [x0, x1] = xr;
  const dx = (x1 - x0) / steps;
  const regions = [];
  let seg = null;
  for (let i = 0; i <= steps; i++) {
    const x = x0 + i * dx;
    const y = fn(x);
    const sat = (type === "<" || type === "≤") ? y < k : y > k;
    if (sat && !seg) seg = x;
    if (!sat && seg != null) { regions.push([seg, x]); seg = null; }
  }
  if (seg != null) regions.push([seg, x1]);
  return regions;
}

function DragGraph({ spec, onConclude }) {
  const { fn, xr, yr, questionTex, type, tipTex, padType, a } = spec;
  // phase: "drag" → "pad" → "done"
  const [phase, setPhase]     = useState("drag");
  const [k, setK]             = useState(0);
  const [dragging, setDragging] = useState(false);
  const [padVal, setPadVal]   = useState("");
  const [padState, setPadState] = useState("idle"); // idle|correct|wrong
  const svgRef = useRef(null);

  const c = mkC(xr[0], xr[1], yr[0], yr[1], 254, 158);
  const { W, H, sx, sy } = c;

  // Convert screen Y → math Y, clamped — only in drag phase
  const screenToK = useCallback((clientY) => {
    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect) return 0;
    const py = (clientY - rect.top) / rect.height * H;
    const raw = yr[1] - (py / H) * (yr[1] - yr[0]);
    return Math.max(yr[0] + 0.4, Math.min(yr[1] - 0.4, raw));
  }, [yr]);

  const onStart = useCallback((e) => {
    if (phase !== "drag") return;
    e.preventDefault();
    setDragging(true);
    setK(screenToK(e.touches ? e.touches[0].clientY : e.clientY));
  }, [phase, screenToK]);

  const onMove = useCallback((e) => {
    if (!dragging) return;
    e.preventDefault();
    setK(screenToK(e.touches ? e.touches[0].clientY : e.clientY));
  }, [dragging, screenToK]);

  const onEnd = useCallback(() => setDragging(false), []);

  useEffect(() => {
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onEnd);
    window.addEventListener("touchmove", onMove, { passive: false });
    window.addEventListener("touchend", onEnd);
    return () => {
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onEnd);
      window.removeEventListener("touchmove", onMove);
      window.removeEventListener("touchend", onEnd);
    };
  }, [onMove, onEnd]);

  const kR = Math.round(k * 10) / 10;
  const lineY = sy(kR);
  const roots = findRoots(fn, kR, xr);
  const shadeRegions = mkDragShade(fn, kR, type, xr, c);
  const shadeCol = (type === "<" || type === "≤") ? "rgba(239,68,68,.15)" : "rgba(16,185,129,.15)";
  const canProceed = phase === "drag" && roots.length > 0;

  // Validate the pad answer
  const validatePad = (val) => {
    if (padState !== "idle") return;
    const ok = val.trim() === a.trim();
    setPadState(ok ? "correct" : "wrong");
    setPhase("done");
    onConclude(ok);
  };

  // ── SVG Graph (shared between phases) ──────────────────────────────────────
  const svgGraph = (
    <div style={{position:"relative",borderRadius:10,overflow:"hidden",
      border:`1.5px solid ${phase==="done"&&padState==="correct"?"#10B981":phase==="done"?"#EF4444":"#E2E8F0"}`,
      background:"#FAFCFF",flexShrink:0,
      cursor:phase==="drag"?(dragging?"grabbing":"grab"):"default",
      touchAction:"none"}}>
      <svg ref={svgRef} viewBox={`0 0 ${W} ${H}`}
        style={{width:"100%",display:"block",maxHeight:155}}
        onMouseDown={onStart} onTouchStart={onStart}>
        {/* Shade (inequalities) */}
        {type && shadeRegions.map(([x1,x2],i)=>{
          const px1=Math.max(0,sx(x1)), px2=Math.min(W,sx(x2));
          if(px2<=px1) return null;
          return <rect key={i} x={px1} y={0} width={px2-px1} height={H} fill={shadeCol}/>;
        })}
        <Axes c={c}/>
        <path d={mkPath(fn,c,200)} stroke="#2563EB" strokeWidth={2.2} fill="none"
          strokeLinecap="round" strokeLinejoin="round"/>
        {/* Horizontal line */}
        <line x1={0} y1={lineY} x2={W} y2={lineY}
          stroke="#F59E0B" strokeWidth={10} strokeOpacity={dragging ? 0.22 : 0.08}/>
        <line x1={0} y1={lineY} x2={W} y2={lineY}
          stroke="#F59E0B" strokeWidth={2} strokeDasharray="5,3"/>
        {/* y=k label */}
        <rect x={W-38} y={lineY-9} width={38} height={13} rx={4}
          fill="#FAFCFF" fillOpacity={0.92}/>
        <text x={W-19} y={lineY+1.5} textAnchor="middle" fontSize={8.5}
          fill="#B45309" fontWeight="bold" fontFamily="DM Sans">y = {kR}</text>
        {/* Handle (only in drag phase) */}
        {phase==="drag"&&<>
          <circle cx={10} cy={lineY} r={10}
            fill={dragging?"#F59E0B":"#FEF3C7"} stroke="#F59E0B" strokeWidth={2}/>
          <text x={10} y={lineY+4} textAnchor="middle" fontSize={11}
            fill="#92400E" fontFamily="DM Sans" fontWeight="bold">⇕</text>
        </>}
        {/* Intersection points */}
        {roots.map((xi,i)=>{
          const px=sx(xi);
          if(px<4||px>W-4) return null;
          return (
            <g key={i}>
              <line x1={px} y1={lineY} x2={px} y2={sy(0)}
                stroke="#F59E0B" strokeWidth={1.2} strokeDasharray="3,3" strokeOpacity={0.7}/>
              <circle cx={px} cy={lineY} r={5.5} fill="#F59E0B" stroke="#fff" strokeWidth={1.5}/>
              <rect x={px-14} y={sy(0)+3} width={28} height={13} rx={5} fill="#F59E0B"/>
              <text x={px} y={sy(0)+12} textAnchor="middle" fontSize={8}
                fill="#78350F" fontWeight="bold" fontFamily="DM Sans">x={fmtX(xi)}</text>
            </g>
          );
        })}
      </svg>
      {/* Drag hint */}
      {phase==="drag"&&!dragging&&(
        <div style={{position:"absolute",bottom:5,left:"50%",transform:"translateX(-50%)",
          background:"rgba(30,41,59,.8)",borderRadius:20,padding:"3px 10px",
          fontSize:10,color:"#94A3B8",fontWeight:700,whiteSpace:"nowrap",pointerEvents:"none"}}>
          ☝️ Fais glisser la droite jaune
        </div>
      )}
      {/* "position locked" badge in pad/done phase */}
      {phase!=="drag"&&(
        <div style={{position:"absolute",top:5,right:5,
          background:"rgba(30,41,59,.85)",borderRadius:20,padding:"3px 8px",
          fontSize:10,color:"#94A3B8",fontWeight:700,pointerEvents:"none"}}>
          🔒 y = {kR}
        </div>
      )}
    </div>
  );

  return (
    <div style={{display:"flex",flexDirection:"column",gap:8,flexShrink:0}}>

      {/* Question banner */}
      <div style={{background:"#EFF6FF",borderRadius:10,padding:"7px 12px",
        fontSize:13,fontWeight:800,color:"#1D4ED8",
        display:"flex",alignItems:"center",gap:8,flexShrink:0}}>
        <span>📐</span>
        <M tex={questionTex}/>
      </div>

      {/* SVG */}
      {svgGraph}

      {/* Live intersections */}
      <div style={{background:"#F8FAFC",border:"1.5px solid #E2E8F0",borderRadius:10,
        padding:"7px 12px",display:"flex",alignItems:"center",gap:8,flexShrink:0}}>
        <span style={{fontSize:12}}>🎯</span>
        {roots.length===0
          ? <span style={{fontSize:11,color:"#94A3B8",fontWeight:600}}>Aucune intersection visible</span>
          : <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
              {roots.map((xi,i)=>(
                <span key={i} style={{background:"#FEF3C7",border:"1.5px solid #F59E0B",
                  borderRadius:7,padding:"2px 8px",fontSize:12,fontWeight:800,color:"#92400E",
                  fontFamily:"'DM Sans',sans-serif"}}>x = {fmtX(xi)}</span>
              ))}
            </div>
        }
        <span style={{marginLeft:"auto",fontSize:10,color:"#94A3B8",
          fontFamily:"'DM Sans',sans-serif",flexShrink:0}}>y = {kR}</span>
      </div>

      {/* Tip */}
      <div style={{background:"#EFF6FF",borderRadius:9,padding:"6px 11px",
        fontSize:11,color:"#3B82F6",fontWeight:600,flexShrink:0}}>
        💡 <M tex={tipTex}/>
      </div>

      {/* ── PHASE DRAG : bouton "Valider ma position" ── */}
      {phase==="drag" && canProceed && (
        <button onClick={()=>setPhase("pad")} className="pop-in" style={{
          padding:"12px",border:"none",borderRadius:12,
          background:"linear-gradient(135deg,#F59E0B,#D97706)",
          color:"#fff",fontFamily:"'Nunito',sans-serif",fontSize:14,fontWeight:800,
          cursor:"pointer",boxShadow:"0 5px 15px rgba(245,158,11,.35)",flexShrink:0}}>
          ✅ Position validée — je conclus ↓
        </button>
      )}

      {/* ── PHASE PAD : saisie de la solution ── */}
      {phase==="pad" && (
        <div className="fade-in" style={{flexShrink:0}}>
          <div style={{fontSize:12,fontWeight:700,color:"#475569",
            marginBottom:7,textAlign:"center"}}>
            {padType==="eq"
              ? "Maintenant tape l'ensemble solution S={…}"
              : "Maintenant tape l'ensemble solution"}
          </div>
          {padType==="eq"
            ? <EqPad  value={padVal} onChange={setPadVal} onValidate={validatePad}
                state={padState} correctAnswer={a}/>
            : <SolPad value={padVal} onChange={setPadVal} onValidate={validatePad}
                state={padState} correctAnswer={a}/>
          }
        </div>
      )}

      {/* ── PHASE DONE : feedback ── */}
      {phase==="done" && (
        <div className="fade-in" style={{
          background:padState==="correct"?"#ECFDF5":"#FEF2F2",
          border:`2px solid ${padState==="correct"?"#10B981":"#EF4444"}`,
          borderRadius:12,padding:"11px 14px",flexShrink:0}}>
          <div style={{fontSize:12,fontWeight:700,
            color:padState==="correct"?"#065F46":"#991B1B",marginBottom:4}}>
            {padState==="correct" ? "✅ Parfait !" : "❌ Pas tout à fait — la correction :"}
          </div>
          <div style={{fontSize:15,fontWeight:900,color:"#1E293B"}}>
            <M tex={padType==="eq" ? `S=${a}` : `S=\\,${a}`}/>
          </div>
        </div>
      )}
    </div>
  );
}
// ═══════════════════════════════════════════════════════════════════════════════

// Single interactive cell: fixed value or hole to fill
function TCell({ cell, filled, active, validated, onActivate }) {
  if (!cell.hole) {
    const isArr = cell.kind === "arrow";
    return (
      <div style={{display:"flex",alignItems:"center",justifyContent:"center",
        fontSize:isArr?16:12, fontWeight:isArr?900:700,
        color:isArr?"#2563EB":"#1E293B", padding:"3px 2px", lineHeight:1}}>
        {cell.v}
      </div>
    );
  }
  const ok  = validated && filled === cell.v;
  const ko  = validated && filled !== cell.v;
  const isArr = cell.kind === "arrow";
  return (
    <div onClick={onActivate} style={{
      display:"flex",alignItems:"center",justifyContent:"center",
      border:`1.5px ${active&&!validated?"solid":"dashed"} ${ok?"#10B981":ko?"#EF4444":active?"#2563EB":"#94A3B8"}`,
      borderRadius:6, cursor:validated?"default":"pointer",
      background:ok?"#ECFDF5":ko?"#FEF2F2":active?"#EFF6FF":"#F8FAFC",
      color:ok?"#065F46":ko?"#EF4444":active?"#1D4ED8":"#94A3B8",
      fontSize:isArr?15:12, fontWeight:800,
      minWidth:isArr?26:22, minHeight:24, padding:"3px 4px",
      transition:"all .12s"
    }}>
      {validated ? cell.v : (filled || "?")}
    </div>
  );
}

// Arrow picker: ↗ / ↘
function ArrowPicker({ onPick }) {
  return (
    <div style={{display:"flex",gap:10,flexShrink:0}}>
      {["↗","↘"].map(a=>(
        <button key={a} onClick={()=>onPick(a)} style={{
          flex:1, height:58, fontSize:28, fontWeight:900,
          background:"#EFF6FF", border:"2.5px solid #3B82F6",
          borderRadius:14, cursor:"pointer", color:"#1D4ED8",
          boxShadow:"0 4px 14px rgba(59,130,246,.2)"
        }}>{a}</button>
      ))}
    </div>
  );
}

// Sign picker: + / −
function SignPicker({ onPick }) {
  const opts=[{v:"+",bg:"#ECFDF5",bd:"#10B981",tc:"#065F46"},
              {v:"-",bg:"#FEF2F2",bd:"#EF4444",tc:"#991B1B"}];
  return (
    <div style={{display:"flex",gap:10,flexShrink:0}}>
      {opts.map(o=>(
        <button key={o.v} onClick={()=>onPick(o.v)} style={{
          flex:1, height:58, fontSize:26, fontWeight:900,
          background:o.bg, border:`2.5px solid ${o.bd}`,
          borderRadius:14, cursor:"pointer", color:o.tc,
          boxShadow:`0 4px 14px ${o.bd}44`
        }}>{o.v}</button>
      ))}
    </div>
  );
}

// Numpad for tableau (with ± for negatives)
function TNumPad({ value, onChange, onValidate }) {
  const keys = ["7","8","9","4","5","6","1","2","3","±","0","⌫"];
  const press = k => {
    if(k==="⌫") { onChange(v=>v.length>0?v.slice(0,-1):""); return; }
    if(k==="±") { onChange(v=>v.startsWith("-")?v.slice(1):v?"-"+v:""); return; }
    if(value.replace("-","").length>=2) return;
    onChange(v=>v+k);
  };
  const canOK = value.length>0 && value!=="-";
  return (
    <div style={{display:"flex",flexDirection:"column",gap:7,flexShrink:0}}>
      <div style={{background:"#F8FAFC",border:"2px solid #CBD5E1",borderRadius:12,
        padding:"7px 12px",textAlign:"center",minHeight:42,
        display:"flex",alignItems:"center",justifyContent:"center"}}>
        <span style={{fontFamily:"'Nunito',sans-serif",fontSize:22,fontWeight:900,
          color:"#1E293B",letterSpacing:2}}>{value||"—"}</span>
      </div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:6}}>
        {keys.map(k=>(
          <button key={k} onClick={()=>press(k)} style={{
            height:44, borderRadius:10, border:"none",
            fontSize:k==="±"||k==="⌫"?15:19, fontWeight:800,
            fontFamily:"'Nunito',sans-serif", cursor:"pointer",
            background:k==="⌫"?"#FEF2F2":k==="±"?"#F1F5F9":"#fff",
            color:k==="⌫"?"#EF4444":k==="±"?"#475569":"#1E293B",
            boxShadow:"0 2px 6px rgba(0,0,0,.07)"
          }}>{k}</button>
        ))}
      </div>
      <button onClick={()=>canOK&&onValidate(value)} style={{
        padding:"12px", border:"none", borderRadius:12,
        background:canOK?"linear-gradient(135deg,#10B981,#059669)":"#E2E8F0",
        color:canOK?"#fff":"#94A3B8", fontFamily:"'Nunito',sans-serif",
        fontSize:14, fontWeight:800, cursor:canOK?"pointer":"not-allowed"
      }}>Confirmer ✓</button>
    </div>
  );
}

// Grid renderer — Tableau de Variations
function TableauVarGrid({ spec, activeFill, fills, validated, onCellClick }) {
  const { xVals, cells } = spec;
  const n = xVals.length;
  // Grid: label col + (2n-1) data cols (alternating value/arrow)
  const gridCols = `24px ${Array(2*n-1).fill("1fr").join(" ")}`;
  return (
    <div style={{border:"1.5px solid #CBD5E1",borderRadius:8,overflow:"hidden",
      background:"#fff",marginBottom:8}}>
      {/* x row */}
      <div style={{display:"grid",gridTemplateColumns:gridCols,
        borderBottom:"1.5px solid #CBD5E1",background:"#F8FAFC",minHeight:26}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"center",
          fontWeight:700,fontSize:10,color:"#64748B",
          borderRight:"1.5px solid #CBD5E1"}}>x</div>
        {cells.map((_,i)=>(
          <div key={`xr${i}`} style={{
            display:"flex",alignItems:"center",justifyContent:"center",
            borderLeft:i%2===0?"1px solid #CBD5E1":"none",
            padding:"3px 1px",fontWeight:700,fontSize:11,color:"#1E293B"
          }}>
            {i%2===0 ? xVals[i/2] : ""}
          </div>
        ))}
      </div>
      {/* f(x) row */}
      <div style={{display:"grid",gridTemplateColumns:gridCols,minHeight:32}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"center",
          fontWeight:700,fontSize:10,color:"#64748B",
          borderRight:"1.5px solid #CBD5E1",flexDirection:"column",lineHeight:1.2,padding:"2px"}}>
          <span>f</span><span style={{fontSize:10}}>(x)</span>
        </div>
        {cells.map((cell,i)=>(
          <div key={`fr${i}`} style={{
            display:"flex",alignItems:"center",justifyContent:"center",
            borderLeft:i%2===0?"1px solid #CBD5E1":"none",
            padding:"3px 1px"
          }}>
            <TCell cell={cell} filled={fills[i]} active={activeFill===i}
              validated={validated}
              onActivate={()=>cell.hole&&!validated&&onCellClick(i)}/>
          </div>
        ))}
      </div>
    </div>
  );
}

// Grid renderer — Tableau de Signes
function TableauSignGrid({ spec, activeFill, fills, validated, onCellClick }) {
  const { xVals, cells, rows } = spec;
  // cells = [sign, 0, sign, 0, ..., sign] pour la ligne f(x) finale
  // rows (optionnel) = [{label, cells:[...]}, ...] pour les lignes intermédiaires (facteurs)
  // Indexation globale : row 0 = [0..cells.length-1], row 1 = [cells.length..2n-1], ..., ligne f = dernière
  const hasRows = Array.isArray(rows) && rows.length > 0;
  const allRows = hasRows ? [...rows, { label: "f(x)", cells, isFinal: true }] : [{ label: "f(x)", cells, isFinal: true }];
  // Offsets des lignes : row i commence à offset[i]
  const offsets = [];
  let off = 0;
  for (const r of allRows) { offsets.push(off); off += r.cells.length; }

  const colDefs = cells.map((_,i)=>i%2===0?"1fr":"26px").join(" ");
  const gridCols = `44px ${colDefs}`;
  return (
    <div style={{border:"1.5px solid #CBD5E1",borderRadius:8,overflow:"hidden",
      background:"#fff",marginBottom:8}}>
      {/* x row */}
      <div style={{display:"grid",gridTemplateColumns:gridCols,
        borderBottom:"1.5px solid #CBD5E1",background:"#F8FAFC",minHeight:24}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"center",
          fontWeight:700,fontSize:10,color:"#64748B",borderRight:"1.5px solid #CBD5E1"}}>x</div>
        {cells.map((_,i)=>{
          const isRoot=i%2===1;
          return (
            <div key={`xr${i}`} style={{
              display:"flex",alignItems:"center",
              justifyContent:i===0?"flex-start":i===cells.length-1?"flex-end":"center",
              borderLeft:isRoot?"1.5px solid #CBD5E1":"1px solid #E2E8F0",
              background:isRoot?"#F1F5F9":"transparent",
              padding:"3px 4px",fontWeight:700,fontSize:11,color:"#1E293B"
            }}>
              {isRoot ? xVals[(i-1)/2+1] : (i===0?"-∞":i===cells.length-1?"+∞":"")}
            </div>
          );
        })}
      </div>
      {/* Toutes les lignes : d'abord facteurs (si rows), puis f(x) final */}
      {allRows.map((row, rowIdx) => {
        const rowOffset = offsets[rowIdx];
        const isFinalRow = row.isFinal;
        return (
          <div key={`row${rowIdx}`} style={{display:"grid",gridTemplateColumns:gridCols,minHeight:30,
            borderTop: rowIdx>0?"1.5px solid #CBD5E1":"none",
            background: isFinalRow && hasRows ? "#FFFBEB" : "transparent"}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"center",
              fontWeight:700,fontSize:10,color:"#64748B",
              borderRight:"1.5px solid #CBD5E1",padding:"2px 4px",
              fontFamily:"'DM Sans',serif"}}>
              <M tex={row.label}/>
            </div>
            {row.cells.map((cell,i)=>{
              const isRoot=i%2===1;
              const globalIdx = rowOffset + i;
              return (
                <div key={`rc${rowIdx}-${i}`} style={{
                  display:"flex",alignItems:"center",justifyContent:"center",
                  borderLeft:isRoot?"1.5px solid #CBD5E1":"1px solid #E2E8F0",
                  background:isRoot?"#F1F5F9":"transparent",
                  padding:"3px 2px"
                }}>
                  <TCell cell={cell} filled={fills[globalIdx]} active={activeFill===globalIdx}
                    validated={validated}
                    onActivate={()=>cell.hole&&!validated&&onCellClick(globalIdx)}/>
                </div>
              );
            })}
          </div>
        );
      })}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════════════════
//  PROBABILITY VISUALS
// ═══════════════════════════════════════════════════════════════════════════════

// Fraction rendered as SVG (num over den with bar)
function SvgFrac({ num, den, cx, cy, col = "#475569", sz = 8.5 }) {
  const w = Math.max(String(num).length, String(den).length) * sz * 0.65 + 5;
  return (
    <g>
      <text x={cx} y={cy} textAnchor="middle" fontSize={sz} fill={col} fontFamily="DM Sans">{num}</text>
      <line x1={cx - w / 2} y1={cy + 2.5} x2={cx + w / 2} y2={cy + 2.5} stroke={col} strokeWidth={0.9} />
      <text x={cx} y={cy + sz + 3} textAnchor="middle" fontSize={sz} fill={col} fontFamily="DM Sans">{den}</text>
    </g>
  );
}

// Probability tree SVG component
// spec: { pA:[n,d], pCA:[n,d], pDA:[n,d], pCBarA:[n,d], pDBarA:[n,d], labelC, labelD }
function ProbaTree({ spec }) {
  const { pA, pCA, pDA, pCBarA, pDBarA, labelC = "C", labelD = "D" } = spec;
  const pBarA = [pA[1] - pA[0], pA[1]];
  const W = 252, H = 164;
  // Coordinates
  const R   = [12,  82];   // root
  const A   = [68,  30];   // first level A
  const BA  = [68, 134];   // first level Ā
  const AC  = [210,  8];   // leaves
  const AD  = [210, 52];
  const BC  = [210, 112];
  const BD  = [210, 156];
  const lx  = 216;         // leaf label x
  const lc  = "#64748B";   // line color

  // Branch midpoints
  const mRA  = [(R[0]+A[0])/2,   (R[1]+A[1])/2];
  const mRBA = [(R[0]+BA[0])/2,  (R[1]+BA[1])/2];
  const mAC  = [(A[0]+AC[0])/2,  (A[1]+AC[1])/2];
  const mAD  = [(A[0]+AD[0])/2,  (A[1]+AD[1])/2];
  const mBAC = [(BA[0]+BC[0])/2, (BA[1]+BC[1])/2];
  const mBAD = [(BA[0]+BD[0])/2, (BA[1]+BD[1])/2];

  return (
    <svg viewBox={`0 0 ${W} ${H}`}
      style={{ width: "100%", maxHeight: 164, display: "block", background: "#FAFCFF", borderRadius: 8, border: "1px solid #E2E8F0" }}>
      {/* Branch lines */}
      <line x1={R[0]} y1={R[1]} x2={A[0]}  y2={A[1]}  stroke={lc} strokeWidth={1.5} />
      <line x1={R[0]} y1={R[1]} x2={BA[0]} y2={BA[1]} stroke={lc} strokeWidth={1.5} />
      <line x1={A[0]}  y1={A[1]}  x2={AC[0]} y2={AC[1]} stroke={lc} strokeWidth={1.5} />
      <line x1={A[0]}  y1={A[1]}  x2={AD[0]} y2={AD[1]} stroke={lc} strokeWidth={1.5} />
      <line x1={BA[0]} y1={BA[1]} x2={BC[0]} y2={BC[1]} stroke={lc} strokeWidth={1.5} />
      <line x1={BA[0]} y1={BA[1]} x2={BD[0]} y2={BD[1]} stroke={lc} strokeWidth={1.5} />

      {/* Node label A */}
      <text x={A[0]-4}  y={A[1]-6}   textAnchor="end" fontSize={12} fill="#2563EB" fontWeight="bold" fontFamily="DM Sans">A</text>
      {/* Node label Ā (A with overline bar) */}
      <text x={BA[0]-4} y={BA[1]+14} textAnchor="end" fontSize={12} fill="#7C3AED" fontWeight="bold" fontFamily="DM Sans">A</text>
      <line x1={BA[0]-14} y1={BA[1]+2} x2={BA[0]-4} y2={BA[1]+2} stroke="#7C3AED" strokeWidth={1.2} />

      {/* Leaf labels */}
      <text x={lx} y={AC[1]+4}  fontSize={12} fill="#2563EB" fontWeight="bold" fontFamily="DM Sans">{labelC}</text>
      <text x={lx} y={AD[1]+4}  fontSize={12} fill="#2563EB" fontWeight="bold" fontFamily="DM Sans">{labelD}</text>
      <text x={lx} y={BC[1]+4}  fontSize={12} fill="#7C3AED" fontWeight="bold" fontFamily="DM Sans">{labelC}</text>
      <text x={lx} y={BD[1]+4}  fontSize={12} fill="#7C3AED" fontWeight="bold" fontFamily="DM Sans">{labelD}</text>

      {/* Branch probability fractions */}
      <SvgFrac num={pA[0]}     den={pA[1]}     cx={mRA[0]-4}  cy={mRA[1]-14} />
      <SvgFrac num={pBarA[0]}  den={pBarA[1]}  cx={mRBA[0]-4} cy={mRBA[1]+6} />
      <SvgFrac num={pCA[0]}    den={pCA[1]}    cx={mAC[0]+4}  cy={mAC[1]-13} />
      <SvgFrac num={pDA[0]}    den={pDA[1]}    cx={mAD[0]+4}  cy={mAD[1]+5} />
      <SvgFrac num={pCBarA[0]} den={pCBarA[1]} cx={mBAC[0]+4} cy={mBAC[1]-13} />
      <SvgFrac num={pDBarA[0]} den={pDBarA[1]} cx={mBAD[0]+4} cy={mBAD[1]+5} />
    </svg>
  );
}

// Probability double-entry table (HTML)
// spec: { rows, cols, data:[[]], hi:[{r,c}] }
function ProbaTable({ spec }) {
  const { rows, cols, data, hi = [] } = spec;
  const isHi = (r, c) => hi.some(h => h.r === r && h.c === c);
  const isTotal = (r, c) => r === rows.length - 1 || c === cols.length - 1;

  const cs = (r, c, head) => ({
    border: "1px solid #CBD5E1",
    padding: "5px 7px",
    fontSize: 11,
    textAlign: "center",
    background: isHi(r, c) ? "#FEF3C7" : head ? "#F1F5F9" : isTotal(r, c) ? "#F8FAFC" : "#fff",
    fontWeight: isHi(r, c) || head || isTotal(r, c) ? 700 : 500,
    color: isHi(r, c) ? "#92400E" : "#1E293B",
    whiteSpace: "nowrap",
  });

  return (
    <div style={{ overflowX: "auto", margin: "6px 0 2px" }}>
      <table style={{ borderCollapse: "collapse", width: "100%", tableLayout: "auto" }}>
        <thead>
          <tr>
            <td style={{ ...cs(-1,-1,true), background:"#E2E8F0" }}></td>
            {cols.map((c, i) => <td key={i} style={cs(-1, i, true)}>{c}</td>)}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, r) => (
            <tr key={r}>
              <td style={cs(r, -1, true)}>{row}</td>
              {data[r].map((val, c) => <td key={c} style={cs(r, c, false)}>{val}</td>)}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

