const getAllQ   = () => Object.values(DB).flatMap(cat => Object.values(cat).flat());
const getCatQ  = id => Object.values(DB[id] || {}).flat();
const getSubQ  = (catId, subIds) => subIds.flatMap(s => DB[catId]?.[s] || []);
const starsFor = (s, t) => { const p = s/t; return p>=.9?3:p>=.6?2:p>=.3?1:0; };

