const PK = (c,s) => `prg:${c}:${s}`;
const PROF_K = 'user:prof';
const LAST_SHARE_K = 'user:last_share'; // date ISO du dernier envoi du lien au prof
const EMPTY_P = () => ({pc:0,pt:0,tb:0,stars:0});

