// ── Storage keys ─────────────────────────────────────────────────────────────
const DIAG_K    = 'user:diag';      // résultats du diagnostic
const PROGRAM_K = 'user:program';   // programme hebdo
const SRS_K     = c => `srs:${c}`; // spaced repetition per catId:subId

async function loadDiag()      { try{const r=await _storage.get(DIAG_K);return r?.value?JSON.parse(r.value):null;}catch{return null;} }
