// ── CollectionScreen — grille de toutes les cartes, filtrables par série ────
function CollectionScreen({onBack, cardsUnlocked}) {
  const [filter, setFilter] = useState("all"); // "all" | "histoire" | "world_tour"
  const [selected, setSelected] = useState(null); // carte sélectionnée (zoom)

  const filtered = filter === "all" ? CARDS : CARDS.filter(c => c.series === filter);
  const totalUnlocked = cardsUnlocked.filter(id => CARDS.some(c => c.id === id)).length;
  const totalCards = CARDS.length;
  const histUnlocked = CARDS.filter(c=>c.series==="histoire" && cardsUnlocked.includes(c.id)).length;
  const histTotal    = CARDS.filter(c=>c.series==="histoire").length;
  const wtUnlocked   = CARDS.filter(c=>c.series==="world_tour" && cardsUnlocked.includes(c.id)).length;
  const wtTotal      = CARDS.filter(c=>c.series==="world_tour").length;

  const filters = [
    {id:"all",         label:`Toutes (${totalUnlocked}/${totalCards})`},
    {id:"histoire",    label:`📜 Histoire (${histUnlocked}/${histTotal})`},
    {id:"world_tour",  label:`🌍 Voyage (${wtUnlocked}/${wtTotal})`},
  ];

  return (
    <div className="slide-up" style={{display:"flex", flexDirection:"column", height:"100%",
      padding:"20px 18px", background:"var(--am-bg-light)"}}>
      <Back onClick={onBack}/>
      <div style={{marginBottom:12}}>
        <h2 style={{fontFamily:"'Nunito',sans-serif", fontSize:22, fontWeight:900,
          color:"#1E293B", margin:0}}>
          🎴 Ma collection
        </h2>
        <p style={{color:"#64748B", fontSize:12, fontWeight:600, marginTop:4}}>
          Débloque des cartes en t'entraînant régulièrement
        </p>
      </div>
      {/* Filtres */}
      <div style={{display:"flex", gap:6, marginBottom:12, overflowX:"auto", flexShrink:0}}>
        {filters.map(f => (
          <button key={f.id} onClick={()=>setFilter(f.id)}
            style={{
              padding:"7px 12px", borderRadius:10, border:"none",
              background: filter===f.id ? "var(--am-bg-dark-1)" : "#fff",
              color: filter===f.id ? "#F59E0B" : "#64748B",
              fontFamily:"'Nunito',sans-serif", fontWeight:800, fontSize:11,
              cursor:"pointer", whiteSpace:"nowrap", flexShrink:0,
              boxShadow: filter===f.id ? "0 3px 10px rgba(0,0,0,.15)" : "0 1px 4px rgba(0,0,0,.05)"
            }}>
            {f.label}
          </button>
        ))}
      </div>
      {/* Grille */}
      <Scroll>
        <div style={{
          display:"grid", gridTemplateColumns:"repeat(2, 1fr)",
          gap:10, paddingBottom:20
        }}>
          {filtered.map(card => {
            const unlocked = cardsUnlocked.includes(card.id);
            return (
              <div key={card.id} onClick={()=>setSelected({card, unlocked})}
                style={{cursor:"pointer", display:"flex", justifyContent:"center"}}>
                <CardView card={card} unlocked={unlocked} size="small"/>
              </div>
            );
          })}
        </div>
      </Scroll>
      {/* Détail d'une carte (modale simple) */}
      {selected && (
        <div onClick={()=>setSelected(null)} style={{
          position:"fixed", inset:0, background:"rgba(15,23,42,.82)",
          zIndex:1000, display:"flex", flexDirection:"column",
          alignItems:"center", justifyContent:"center", padding:20
        }}>
          <CardView card={selected.card} unlocked={selected.unlocked} size="normal"/>
          {/* Objectif */}
          <div style={{
            marginTop:16, padding:"10px 14px", background:"#fff", borderRadius:12,
            maxWidth:280, textAlign:"center", boxShadow:"0 6px 20px rgba(0,0,0,.2)"
          }}>
            <div style={{fontSize:10, color:"#64748B", fontWeight:700, textTransform:"uppercase", letterSpacing:.5, marginBottom:4}}>
              {selected.unlocked ? "✅ Débloquée" : "🔒 Objectif"}
            </div>
            <div style={{fontSize:12, color:"#1E293B", fontWeight:600, lineHeight:1.4}}>
              {CARDS_OBJECTIVES[selected.card.id]?.label || ""}
            </div>
          </div>
          <button onClick={()=>setSelected(null)} style={{
            marginTop:14, padding:"8px 20px", borderRadius:20, border:"none",
            background:"#F59E0B", color:"#fff", fontFamily:"'Nunito',sans-serif",
            fontWeight:900, fontSize:12, cursor:"pointer"
          }}>Fermer</button>
        </div>
      )}
    </div>
  );
}

