// ── TrainingModesScreen — écran intermédiaire pour choisir le format d'entraînement
function TrainingModesScreen({onMode, onBack}) {
  const modes = [
    {
      id:"express",
      label:"Express",
      sub:"10 questions dans un thème",
      desc:"Parfait pour une pause rapide : tu choisis un thème, Sigma te donne 10 questions.",
      emoji:"⚡",
      grad:"linear-gradient(135deg,#0EA5E9,#0284C7)",
    },
    {
      id:"entrainement",
      label:"Entraînement",
      sub:"20 ou 50 questions par thème",
      desc:"Pour une vraie séance de travail ciblée sur tes thèmes.",
      emoji:"💪",
      grad:"linear-gradient(135deg,#8B5CF6,#6D28D9)",
    },
    {
      id:"missions",
      label:"Missions",
      sub:"Objectifs Sigma",
      desc:"Accomplis des missions pour gagner des récompenses et progresser par paliers.",
      emoji:"🚀",
      grad:"linear-gradient(135deg,#1E40AF,#1E3A8A)",
    },
    {
      id:"test_aleatoire",
      label:"Test aléatoire",
      sub:"Questions surprises",
      desc:"Sigma mélange les thèmes — idéal pour simuler une évaluation.",
      emoji:"🎲",
      grad:"linear-gradient(135deg,#10B981,#047857)",
    },
  ];
  return (
    <div className="slide-up" style={{display:"flex",flexDirection:"column",height:"100%",
      padding:"20px 18px",background:"var(--am-bg-light)"}}>
      <Back onClick={onBack}/>
      <div style={{marginBottom:16}}>
        <h2 style={{fontFamily:"'Nunito',sans-serif",fontSize:22,fontWeight:900,color:"#1E293B",margin:0}}>
          💪 S'entraîner
        </h2>
        <p style={{color:"#64748B",fontSize:12,fontWeight:600,marginTop:4}}>
          Choisis ton format
        </p>
      </div>
      <Scroll>
        {modes.map((m,i)=>(
          <button key={m.id} onClick={()=>onMode(m.id)} className="pop-in"
            style={{background:m.grad,border:"none",borderRadius:16,padding:"18px",
              cursor:"pointer",display:"flex",flexDirection:"column",alignItems:"flex-start",gap:8,
              boxShadow:"0 5px 18px rgba(0,0,0,.15)",animationDelay:`${i*.07}s`,flexShrink:0,marginBottom:12,textAlign:"left"}}>
            <div style={{display:"flex",alignItems:"center",gap:14,width:"100%"}}>
              <div style={{fontSize:28,width:48,height:48,background:"rgba(255,255,255,.2)",
                borderRadius:13,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                {m.emoji}
              </div>
              <div style={{flex:1}}>
                <div style={{fontFamily:"'Nunito',sans-serif",fontSize:17,fontWeight:900,color:"#fff"}}>
                  {m.label}
                </div>
                <div style={{fontSize:12,color:"rgba(255,255,255,.85)",marginTop:2}}>{m.sub}</div>
              </div>
              <div style={{color:"rgba(255,255,255,.7)",fontSize:20}}>›</div>
            </div>
            <div style={{fontSize:11,color:"rgba(255,255,255,.85)",lineHeight:1.5,
              background:"rgba(255,255,255,.1)",borderRadius:10,padding:"8px 12px",width:"100%"}}>
              {m.desc}
            </div>
          </button>
        ))}
      </Scroll>
    </div>
  );
}

function SubmodeScreen({mode,onSubmode,onBack}) {
  const isR=mode==="rapide";
  return (
    <div className="slide-up" style={{display:"flex",flexDirection:"column",height:"100%",padding:"20px 18px"}}>
      <Back onClick={onBack}/>
      <h2 style={{fontFamily:"'Nunito',sans-serif",fontSize:22,fontWeight:900,color:"#1E293B",marginBottom:18}}>{isR?"Entraînement rapide":"Entraînement long"}</h2>
      <div style={{display:"flex",flexDirection:"column",gap:12}}>
        <button onClick={()=>onSubmode("categories")} style={{background:"#fff",border:"2px solid #BFDBFE",borderRadius:16,padding:"18px",cursor:"pointer",textAlign:"left",boxShadow:"0 3px 12px rgba(0,0,0,.07)"}}>
          <div style={{fontFamily:"'Nunito',sans-serif",fontSize:17,fontWeight:900,color:"#1E293B",marginBottom:4}}>📚 Par catégories</div>
          <div style={{fontSize:13,color:"#64748B"}}>Sous-thèmes → {isR?"10":"20"} questions</div>
        </button>
        <button onClick={()=>onSubmode("complet")} style={{background:"#fff",border:"2px solid #DDD6FE",borderRadius:16,padding:"18px",cursor:"pointer",textAlign:"left",boxShadow:"0 3px 12px rgba(0,0,0,.07)"}}>
          <div style={{fontFamily:"'Nunito',sans-serif",fontSize:17,fontWeight:900,color:"#1E293B",marginBottom:4}}>🎲 Complet</div>
          <div style={{fontSize:13,color:"#64748B"}}>{isR?"20":"50"} questions aléatoires</div>
        </button>
      </div>
    </div>
  );
}

