const NIVEAU_LABELS = {
  "sec":  "2nde",
  "tc":   "1ère — Tronc commun",
  "stmg": "1ère Techno",
  "spe":  "1ère Spé",
  "term": "Terminale Spé",
};
const NIVEAU_COLORS = {
  "sec":  "#0369A1",
  "tc":   "#2563EB",
  "stmg": "#059669",
  "spe":  "#DC2626",
  "term": "#7C3AED",
};
// Mapping profil élève → identifiant niveau filtre
const LEVEL_MAP = {
  seconde:       "sec",
  premiere_tronc:"tc",
  premiere_stmg: "stmg",
  premiere_spe:  "spe",
  terminale_spe: "term",
};

function SubcategoryScreen({catId,qCount,onStart,onBack,onLevelPicker,defaultNiveau=null}) {
  const cat=getCat(catId);
  const [niveau,setNiveau]=useState(defaultNiveau);
  const [sel,setSel]=useState([]);
  const [typeFilter,setTypeFilter]=useState(null); // null | "qcm" | "pad" | "drag" | "tableau"
  const [collapsedGroups, setCollapsedGroups] = useState(() => {
    // Tous les groupes repliés par défaut
    const init = {};
    const cat = getCat(catId);
    if (cat?.groups) {
      cat.groups.forEach(g => { init[`${catId}_${g.id}`] = true; });
    }
    return init;
  });

  // Guard : catégorie introuvable (ex: catId="bac" en mode mission)
  if (!cat) return null;

  const levelsInCat=[...new Set(cat.subs.flatMap(s=>s.levels||[]))];
  const normalSubs = cat.subs.filter(s=>!s.levelPicker && !s.isMission);
  
  // Filtrer par niveau ET par type
  let visibleSubs = niveau
    ? normalSubs.filter(s=>!s.levels || s.levels.includes(niveau))
    : normalSubs;
  
  // Appliquer le filtre de type (garde les subs qui contiennent au moins une question de ce type)
  if (typeFilter) {
    visibleSubs = visibleSubs.filter(s => {
      const types = getQuestionTypes(catId, s.id);
      return types.includes(typeFilter);
    });
  }
  
  // LevelPicker items visibles selon le niveau
  const visiblePickers = cat.subs.filter(s=>s.levelPicker && (!niveau || !s.levels || s.levels.includes(niveau)));
  // Missions visibles selon le niveau (les missions ont isMission:true, pas dans normalSubs)
  const visibleMissions = cat.subs.filter(s=>s.isMission && (!niveau || !s.levels || s.levels.includes(niveau)));
  const hasAnything = visibleSubs.length>0 || visiblePickers.length>0 || visibleMissions.length>0;

  // Détecter les types disponibles dans la catégorie
  const availableTypes = new Set();
  normalSubs.forEach(s => {
    const types = getQuestionTypes(catId, s.id);
    types.forEach(t => availableTypes.add(t));
  });

  const toggle=id=>setSel(s=>s.includes(id)?s.filter(x=>x!==id):[...s,id]);
  const toggleAll=()=>setSel(s=>visibleSubs.every(s2=>s.includes(s2.id))?s.filter(id=>!visibleSubs.find(s2=>s2.id===id)):[...new Set([...s,...visibleSubs.map(s2=>s2.id)])]);
  const allVis=visibleSubs.length>0&&visibleSubs.every(s=>sel.includes(s.id));
  const pool=getSubQ(catId,sel);
  const canStart=sel.length>0&&pool.length>0;
  
  return (
    <div className="slide-up" style={{display:"flex",flexDirection:"column",height:"100%",padding:"20px 18px 16px"}}>
      <Back onClick={onBack}/>
      <Breadcrumb items={["Catégories", cat.label]} />
      <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:8}}>
        <div style={{width:40,height:40,borderRadius:12,background:cat.grad,display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,flexShrink:0}}>{cat.emoji}</div>
        <h2 style={{fontFamily:"'Nunito',sans-serif",fontSize:19,fontWeight:900,color:"#1E293B",margin:0}}>{cat.label}</h2>
      </div>
      <p style={{color:"#64748B",fontSize:12,marginBottom:12}}>{qCount} questions</p>

      {/* Filtres de niveau — pré-sélectionnés sur le niveau du profil si connecté */}
      {levelsInCat.length>0&&(
        <div style={{display:"flex",gap:6,marginBottom:8,flexWrap:"wrap"}}>
          <button onClick={()=>{setNiveau(null);setSel([]);}}
            style={{padding:"5px 12px",borderRadius:20,border:`1.5px solid ${!niveau?"#1E293B":"#E2E8F0"}`,
              background:!niveau?"#1E293B":"#fff",color:!niveau?"#fff":"#64748B",
              fontSize:11,fontWeight:700,cursor:"pointer"}}>Tous</button>
          {["sec","tc","stmg","spe","term"].filter(lv=>levelsInCat.includes(lv)).map(lv=>(
            <button key={lv} onClick={()=>{setNiveau(lv);setSel([]);}}
              style={{padding:"5px 12px",borderRadius:20,
                border:`1.5px solid ${niveau===lv?NIVEAU_COLORS[lv]:"#E2E8F0"}`,
                background:niveau===lv?NIVEAU_COLORS[lv]:"#fff",
                color:niveau===lv?"#fff":"#64748B",
                fontSize:11,fontWeight:700,cursor:"pointer",
                boxShadow:niveau===lv?`0 2px 8px ${NIVEAU_COLORS[lv]}55`:"none"}}>
              {lv===defaultNiveau?"★ ":""}{NIVEAU_LABELS[lv]}
            </button>
          ))}
        </div>
      )}

      {/* Filtres de type de questions */}
      {availableTypes.size > 1 && (
        <div style={{marginBottom:12}}>
          <div style={{fontSize:10,fontWeight:700,color:"#64748B",marginBottom:6,textTransform:"uppercase",letterSpacing:"0.5px"}}>
            Type de réponse
          </div>
          <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
            <button onClick={()=>{setTypeFilter(null);setSel([]);}}
              style={{padding:"5px 12px",borderRadius:20,border:`1.5px solid ${!typeFilter?"#7C3AED":"#E2E8F0"}`,
                background:!typeFilter?"#7C3AED":"#fff",color:!typeFilter?"#fff":"#64748B",
                fontSize:11,fontWeight:700,cursor:"pointer"}}>Tous</button>
            {availableTypes.has("qcm") && (
              <button onClick={()=>{setTypeFilter("qcm");setSel([]);}}
                style={{padding:"5px 12px",borderRadius:20,
                  border:`1.5px solid ${typeFilter==="qcm"?"#10B981":"#E2E8F0"}`,
                  background:typeFilter==="qcm"?"#10B981":"#fff",
                  color:typeFilter==="qcm"?"#fff":"#64748B",
                  fontSize:11,fontWeight:700,cursor:"pointer"}}>
                QCM
              </button>
            )}
            {availableTypes.has("pad") && (
              <button onClick={()=>{setTypeFilter("pad");setSel([]);}}
                style={{padding:"5px 12px",borderRadius:20,
                  border:`1.5px solid ${typeFilter==="pad"?"#F59E0B":"#E2E8F0"}`,
                  background:typeFilter==="pad"?"#F59E0B":"#fff",
                  color:typeFilter==="pad"?"#fff":"#64748B",
                  fontSize:11,fontWeight:700,cursor:"pointer"}}>
                ✍️ Pad
              </button>
            )}
            {availableTypes.has("drag") && (
              <button onClick={()=>{setTypeFilter("drag");setSel([]);}}
                style={{padding:"5px 12px",borderRadius:20,
                  border:`1.5px solid ${typeFilter==="drag"?"#EF4444":"#E2E8F0"}`,
                  background:typeFilter==="drag"?"#EF4444":"#fff",
                  color:typeFilter==="drag"?"#fff":"#64748B",
                  fontSize:11,fontWeight:700,cursor:"pointer"}}>
                🎯 Drag
              </button>
            )}
            {availableTypes.has("tableau") && (
              <button onClick={()=>{setTypeFilter("tableau");setSel([]);}}
                style={{padding:"5px 12px",borderRadius:20,
                  border:`1.5px solid ${typeFilter==="tableau"?"#06B6D4":"#E2E8F0"}`,
                  background:typeFilter==="tableau"?"#06B6D4":"#fff",
                  color:typeFilter==="tableau"?"#fff":"#64748B",
                  fontSize:11,fontWeight:700,cursor:"pointer"}}>
                📊 Tableau
              </button>
            )}
          </div>
        </div>
      )}

      {!hasAnything?(
        <div style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column",gap:10,color:"#94A3B8"}}>
          <span style={{fontSize:36}}>🎓</span>
          <span style={{fontSize:13,fontWeight:600,textAlign:"center"}}>Rien pour ce niveau dans cette section… pour l'instant !</span>
        </div>
      ):(
        <>
          {visibleSubs.length>0&&<button onClick={toggleAll} style={{background:allVis?cat.light:"#F8FAFC",border:`1.5px solid ${allVis?cat.border:"#E2E8F0"}`,borderRadius:12,padding:"8px 14px",cursor:"pointer",fontSize:12,fontWeight:700,color:allVis?cat.color:"#475569",marginBottom:10,textAlign:"left"}}>
            {allVis?"✅ Tout désélectionner":"☑️ Tout sélectionner"}
          </button>}
      <Scroll>
        {(() => {
          // Si la catégorie a des groupes, on trie les subs par ordre des groupes
          // pour que les séparateurs soient cohérents.
          const groups = cat.groups || [];
          const sortedSubs = groups.length === 0
            ? cat.subs
            : [...cat.subs].sort((a, b) => {
                const ga = groups.findIndex(g => g.id === a.group);
                const gb = groups.findIndex(g => g.id === b.group);
                return (ga === -1 ? 999 : ga) - (gb === -1 ? 999 : gb);
              });
          let lastGroup = null;
          const rendered = [];
          sortedSubs.forEach((s, i) => {
          // Filtre niveau pour les subs normales (non-mission, non-levelPicker)
          if (!s.isMission && !s.levelPicker) {
            if (niveau && s.levels && !s.levels.includes(niveau)) return;
            // Filtre par type de réponse (contient au moins une question de ce type)
            if (typeFilter) {
              const types = getQuestionTypes(catId, s.id);
              if (!types.includes(typeFilter)) return;
            }
          }
          // Insérer un séparateur de groupe si nécessaire (catégorie à groupes uniquement)
          if (groups.length > 0 && s.group && s.group !== lastGroup) {
            const groupInfo = groups.find(g => g.id === s.group);
            if (groupInfo) {
              const isCollapsed = !!collapsedGroups[`${catId}_${s.group}`];
              rendered.push(
                <button key={`__group_${s.group}`}
                  onClick={() => setCollapsedGroups(prev => ({
                    ...prev,
                    [`${catId}_${s.group}`]: !prev[`${catId}_${s.group}`]
                  }))}
                  style={{
                    display:"flex", alignItems:"center", justifyContent:"space-between",
                    width:"100%", background:"none", border:"none", cursor:"pointer",
                    padding:"6px 2px",
                    marginTop: rendered.length === 0 ? 0 : 14, marginBottom: isCollapsed ? 0 : 8,
                  }}>
                  <span style={{fontSize:11, fontWeight:800, color:"#64748B",
                    textTransform:"uppercase", letterSpacing:0.8}}>
                    {groupInfo.label}
                  </span>
                  <span style={{fontSize:13, color:"#94A3B8", transition:"transform .2s",
                    display:"inline-block", transform: isCollapsed ? "rotate(-90deg)" : "rotate(0deg)"}}>
                    ▾
                  </span>
                </button>
              );
            }
            lastGroup = s.group;
          }
          // Si le groupe est replié, on skip les sous-catégories
          if (groups.length > 0 && s.group && collapsedGroups[`${catId}_${s.group}`]) return;
          // Special mission entry
          if(s.isMission) {
            if(niveau && s.levels && !s.levels.includes(niveau)) return;
            const disabled = s.disabled || false;
            rendered.push(
            <button key={s.id} 
              onClick={()=>!disabled && onLevelPicker && onLevelPicker(s.id, 'mission')} 
              disabled={disabled}
              className="pop-in"
              style={{background:disabled ? "#F1F5F9" : "linear-gradient(135deg,#F9731618,#C2410C18)",
                border:`2px solid ${disabled ? "#E2E8F0" : "#FED7AA"}`,
                borderRadius:14,padding:"12px 14px",
                cursor:disabled ? "not-allowed" : "pointer",
                display:"flex",alignItems:"center",gap:12,marginBottom:8,
                boxShadow:"0 2px 8px rgba(0,0,0,.04)",animationDelay:`${i*.04}s`,flexShrink:0,
                opacity:disabled ? 0.6 : 1}}>
              <div style={{fontSize:24}}>{disabled ? "🔒" : "🎯"}</div>
              <div style={{flex:1,textAlign:"left"}}>
                <div style={{fontSize:13,fontWeight:800,color:disabled ? "#94A3B8" : "#EA580C"}}>{s.label}</div>
                <div style={{fontSize:10,color:disabled ? "#CBD5E1" : "#F97316",marginTop:3}}>
                  {disabled ? "Bientôt disponible" : "Cliquer pour démarrer →"}
                </div>
              </div>
              <span style={{color:disabled ? "#CBD5E1" : "#EA580C",fontSize:18}}>›</span>
            </button>
          );return;}
          
          // Special levelPicker entry — only show if matches current niveau filter
          if(s.levelPicker) {
            if(niveau && s.levels && !s.levels.includes(niveau)) return;
            rendered.push(
            <button key={s.id} onClick={()=>onLevelPicker&&onLevelPicker(s.id, s.levelType||'racines')} className="pop-in"
              style={{background:"linear-gradient(135deg,#7C3AED18,#5B21B618)",
                border:"2px solid #DDD6FE",borderRadius:14,padding:"12px 14px",cursor:"pointer",
                display:"flex",alignItems:"center",gap:12,marginBottom:8,
                boxShadow:"0 2px 8px rgba(0,0,0,.04)",animationDelay:`${i*.04}s`,flexShrink:0}}>
              <div style={{fontSize:24}}>{s.levelType==="relatifs"?"➕➖":s.levelType==="reduction"?"✏️":s.levelType==="identites"?"🔣":s.levelType==="cercle_trigo"?"⭕":s.levelType==="factorisation"?"✖️":s.levelType==="denominateur"?"➗":"√"}</div>
              <div style={{flex:1,textAlign:"left"}}>
                <div style={{fontSize:13,fontWeight:800,color:"#7C3AED"}}>{s.label}</div>
                <div style={{fontSize:10,color:"#8B5CF6",marginTop:3}}>{s.levelType==="cercle_trigo"?"3 niveaux — Placer l'angle →":"4 niveaux — Choisir la difficulté →"}</div>
              </div>
              <span style={{color:"#7C3AED",fontSize:18}}>›</span>
            </button>
          );return;}
          const on=sel.includes(s.id);
          const types = getQuestionTypes(catId, s.id);
          const typeMeta = {
            qcm:     { label: "QCM",      color: "#10B981" },
            pad:     { label: "✍️ Pad",   color: "#F59E0B" },
            drag:    { label: "🎯 Drag",  color: "#EF4444" },
            tableau: { label: "📊 Tableau", color: "#06B6D4" },
          };
          // Ordre d'affichage stable : qcm, pad, drag, tableau
          const sortedTypes = ["qcm","pad","drag","tableau"].filter(t => types.includes(t));
          
          rendered.push(
            <button key={s.id} onClick={()=>toggle(s.id)} className="pop-in"
              style={{background:on?cat.light:"#fff",border:`2px solid ${on?cat.border:"#E2E8F0"}`,borderRadius:14,padding:"12px 14px",cursor:"pointer",display:"flex",alignItems:"center",gap:12,marginBottom:8,boxShadow:"0 2px 8px rgba(0,0,0,.04)",animationDelay:`${i*.04}s`,flexShrink:0}}>
              <div style={{width:20,height:20,borderRadius:6,background:on?cat.color:"#E2E8F0",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                {on&&<span style={{color:"#fff",fontSize:11,fontWeight:900}}>✓</span>}
              </div>
              <div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"flex-start",gap:3}}>
                <span style={{fontSize:13,fontWeight:600,color:on?cat.color:"#475569",textAlign:"left"}}>{s.label}</span>
                <div style={{display:"flex",gap:4,alignItems:"center",flexWrap:"wrap"}}>
                  {sortedTypes.map(t => {
                    const meta = typeMeta[t];
                    const isFiltered = typeFilter === t;
                    return (
                      <span key={t} style={{fontSize:10,fontWeight:700,padding:"2px 7px",borderRadius:99,
                        background:isFiltered?meta.color:`${meta.color}18`,
                        color:isFiltered?"#fff":meta.color,
                        border:isFiltered?`1.5px solid ${meta.color}`:"none"}}>
                        {meta.label}
                      </span>
                    );
                  })}
                  <span style={{fontSize:10,color:"#94A3B8"}}>{DB[catId][s.id]?.length||0} q.</span>
                </div>
              </div>
            </button>
          );
        });
          return rendered;
        })()}
        </Scroll>
        </>
      )}
      {normalSubs.length>0 && (
      <button onClick={()=>canStart&&onStart(pool)} style={{marginTop:12,border:"none",borderRadius:14,padding:"15px",background:canStart?cat.grad:"#E2E8F0",color:canStart?"#fff":"#94A3B8",fontFamily:"'Nunito',sans-serif",fontSize:14,fontWeight:800,cursor:canStart?"pointer":"not-allowed",flexShrink:0,boxShadow:canStart?`0 5px 16px ${cat.color}44`:"none"}}>
        {canStart?`Démarrer (${Math.min(pool.length,qCount)} questions) →`:"Sélectionne au moins un thème"}
      </button>
      )}
    </div>
  );
}

