function CoursMathScreen({onBack, onOpen, onStartPractice}) {
  const [secIdx, setSecIdx] = React.useState(0);
  React.useLayoutEffect(() => { if (COURS_OPEN_PRACTICE) { COURS_OPEN_PRACTICE = false; const _pi = SECS.findIndex(s => s.isPractice); if (_pi >= 0) setSecIdx(_pi); } }, []);
  React.useEffect(()=>{ if(onOpen) onOpen(); }, []);
  const [openMap, setOpenMap] = React.useState({});
  const tog = k => setOpenMap(p=>({...p,[k]:p[k]===undefined?false:!p[k]}));
  const isOpen = (k,first) => openMap[k]===undefined?first:openMap[k];
  const tabsRef = React.useRef();
  React.useEffect(()=>{
    if(!tabsRef.current) return;
    const btn = tabsRef.current.children[secIdx];
    if(btn) btn.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});
  },[secIdx]);

  const SECS = [
    { emoji:"📊", label:"Proportions", color:"#DB2777", light:"#FDF2F8", rules:[
      { id:"p1",num:"1",title:"Calculer la proportion p",
        fml:r`p = \dfrac{n}{N}`,
        bltTex:[r`E\text{ : ensemble total (}N\text{ éléments)}`,r`A\subset E\text{ : sous-ensemble (}n\text{ éléments)}`,r`p\text{ : proportion de }A\text{ dans }E`],
        tipTex:r`\text{La proportion est toujours entre }0\text{ et }1`,
        ex:{qTex:r`\text{12 filles dans une classe de 30 élèves}`,a:r`p=\dfrac{12}{30}=\dfrac{2}{5}=0{,}4=40\%`}},
      { id:"p2",num:"2",title:"Calculer l'effectif partiel n",
        fml:r`n = p \times N`,bltTex:[r`\text{Connaître }p\text{ et }N`,r`\text{Trouver }n`],
        ex:{qTex:r`\text{Gâteau 1 200 g : 50\% de lait}`,a:r`n=0{,}5\times1200=600\text{ g}`}},
      { id:"p3",num:"3",title:"Calculer l'effectif total N",
        fml:r`N = \dfrac{n}{p}`,bltTex:[r`\text{Connaître }p\text{ et }n`,r`\text{Trouver }N`],
        ex:{qTex:r`\text{133 femmes = 35\% des adhérents}`,a:r`N=\dfrac{133}{0{,}35}=380\text{ adhérents}`}},
      { id:"p4",num:"4",title:"Proportion de proportion",
        fml:r`p_{\text{global}} = p \times p'`,
        bltTex:[r`p\text{ : proportion de }B\text{ dans }E`,r`p'\text{ : proportion de }A\text{ dans }B`,r`p\times p'\text{ : proportion de }A\text{ dans }E`],
        tipTex:r`\text{Attention aux règles de calcul des fractions !}`,
        ex:{qTex:r`\text{30\% de 20\% de 500}`,a:r`0{,}3\times0{,}2\times500=30`}},
    ]},
    { emoji:"📈", label:"Évolutions", color:"#0891B2", light:"#ECFEFF", rules:[
      { id:"e1a",num:"1a",title:"Augmenter de a%",
        fml:r`V_i \times \left(1+\dfrac{a}{100}\right)=V_f`,
        tipTex:r`\text{Ex : }+20\%\rightarrow\times1{,}20\quad\cdot\quad+3\%\rightarrow\times1{,}03`,
        ex:{qTex:r`\text{Salaire 1 500 € augmente de 3\%}`,a:r`1500\times1{,}03=1\,545\text{ €}`}},
      { id:"e1b",num:"1b",title:"Diminuer de a%",
        fml:r`V_i \times \left(1-\dfrac{a}{100}\right)=V_f`,
        tipTex:r`\text{Ex : }-20\%\rightarrow\times0{,}80\quad\cdot\quad-1{,}7\%\rightarrow\times0{,}983`,
        ex:{qTex:r`\text{Retraite 2 400 € baisse de 1,7\%}`,a:r`2400\times0{,}983=2\,359{,}20\text{ €}`}},
      { id:"e2",num:"2",title:"Coefficient Multiplicateur (CM)",
        fml:r`CM = \dfrac{V_{\text{finale}}}{V_{\text{initiale}}}`,
        bltTex:[r`CM>1\text{ → hausse}`,r`CM<1\text{ → baisse}`,r`CM=1\text{ → pas de changement}`],
        ex:{qTex:r`\text{Prix : 46,60 € }\rightarrow\text{ 78,9 €}`,a:r`CM=\dfrac{78{,}9}{46{,}6}\approx1{,}693`}},
      { id:"e2b",num:"2b",title:"Avancer / Remonter dans le temps",
        fml:null,isTimeline:true,
        bltTex:[r`\text{⏩ Avancer dans le temps → multiplier par }CM`,r`\text{⏪ Remonter dans le temps → diviser par }CM`],
        tipTex:r`\text{Erreur classique : on ne soustrait pas le taux — on divise par le }CM\text{ !}`,
        ex:{qTex:r`\text{Appartement vaut 144 000 € après +20\%. Prix initial ?}`,a:r`CM=1{,}2\ \Rightarrow\ V_i=\dfrac{144\,000}{1{,}2}=120\,000\text{ €}`}},
      { id:"e3a",num:"3a",title:"Taux d'évolution depuis le CM",
        fml:r`\text{taux\%} = CM \times 100 - 100`,
        ex:{qTex:r`CM=1{,}693`,a:r`1{,}693\times100-100=+69{,}3\%`}},
      { id:"e3b",num:"3b",title:"CM depuis le taux",
        fml:r`CM = 1 + \dfrac{\text{taux}}{100}`,
        ex:{qTex:r`\text{Taux}=-37{,}2\%`,a:r`CM=1-\dfrac{37{,}2}{100}=0{,}628`}},
    ]},
    { emoji:"🔗", label:"Successives", color:"#7C3AED", light:"#F5F3FF", rules:[
      { id:"s1",num:"4a",title:"CM global",
        fml:r`CM_{\text{global}} = CM_1 \times CM_2 \times \cdots \times CM_n`,
        bltTex:[r`\textbf{Les \% NE s'additionnent PAS !}`,r`\text{On multiplie les }CM.`],
        tipTex:r`+30\%\text{ puis }+40\%\neq+70\%\rightarrow\text{ multiplier les }CM\text{ !}`,
        ex:{qTex:r`+30\%\text{ puis }+40\%`,a:r`1{,}3\times1{,}4=1{,}82\Rightarrow+82\%`}},
      { id:"s2",num:"4b",title:"Taux global",
        fml:r`\text{taux}_{\text{global}} = CM_{\text{global}} \times 100 - 100`,
        ex:{qTex:r`-25\%\text{ puis }+40\%`,a:r`0{,}75\times1{,}4=1{,}05\Rightarrow+5\%`}},
      { id:"s3",num:"4c",title:"Intérêts composés",
        fml:r`CM_{\text{global}} = CM^n`,
        tipTex:r`\text{Placements, croissance démographique…}`,
        ex:{qTex:r`\text{+3\%/an pendant 8 ans}`,a:r`1{,}03^8\approx1{,}267\Rightarrow+26{,}7\%`}},
    ]},
    { emoji:"🔄", label:"Réciproque", color:"#059669", light:"#F0FDF4", rules:[
      { id:"r1",num:"5a",title:"CM réciproque",
        fml:r`CM' = \dfrac{1}{CM}`,
        bltTex:[r`\text{Pour annuler une évolution}`,r`\text{On prend l'inverse du }CM`],
        ex:{qTex:r`\text{Action baisse de 20\%}`,a:r`CM=0{,}8\Rightarrow CM'=\dfrac{1}{0{,}8}=1{,}25\Rightarrow+25\%`}},
      { id:"r2",num:"5b",title:"Méthode en 3 étapes",
        fml:null,
        bltTex:[r`\text{① Trouver le }CM\text{ de l'évolution donnée}`,r`\text{② Calculer }CM'=\dfrac{1}{CM}`,r`\text{③ Convertir }CM'\text{ en taux\%}`],
        ex:{qTex:r`\text{Compenser une hausse de 10\%}`,a:r`CM'=\dfrac{1}{1{,}1}\approx0{,}909\Rightarrow-9{,}1\%`}},
      { id:"r3",num:"5c",title:"Cas classiques à retenir",
        fml:null,
        bltTex:[r`+20\%\leftrightarrow-16{,}7\%\ (\times1{,}2)`,r`+25\%\leftrightarrow-20\%\ (\times1{,}25)`,r`+50\%\leftrightarrow-33{,}3\%\ (\times1{,}5)`,r`-20\%\leftrightarrow+25\%\ (\times0{,}8)`,r`-50\%\leftrightarrow+100\%\ (\times0{,}5)`]},
    ]},
    { emoji:"🏋️", label:"S'entraîner", color:"#0F172A", light:"#F1F5F9", isPractice:true,
      practices:[
        {sub:"proportions",           label:"Proportions",              emoji:"📊", cat:"pourcentages"},
        {sub:"taux_cm",               label:"Taux ↔ Coefficient mult.", emoji:"📈", cat:"pourcentages"},
        {sub:"evolutions_successives",label:"Évolutions successives",   emoji:"🔗", cat:"pourcentages"},
        {sub:"evolution_reciproque",  label:"Taux réciproque",          emoji:"🔄", cat:"pourcentages"},
      ]},
  ];

  const sec = SECS[secIdx];
  const col = sec.color;

  return (
    <div style={{display:"flex",flexDirection:"column",height:"100%",background:"var(--am-bg-light)"}}>
      <div style={{background:`linear-gradient(135deg,${col},${col}CC)`,padding:"14px 18px 0",flexShrink:0}}>
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:10}}>
          <button onClick={onBack} style={{background:"rgba(255,255,255,.2)",border:"none",
            cursor:"pointer",color:"#fff",fontSize:14,borderRadius:99,
            width:30,height:30,display:"flex",alignItems:"center",justifyContent:"center"}}>✕</button>
          <div>
            <div style={{fontFamily:"'Nunito',sans-serif",fontWeight:900,fontSize:16,color:"#fff"}}>Pourcentages &amp; Évolutions</div>
            <div style={{fontSize:10,color:"rgba(255,255,255,.7)"}}>📚 Cours interactif</div>
          </div>
        </div>
        <div ref={tabsRef} style={{display:"flex",gap:6,overflowX:"auto",paddingBottom:12,scrollbarWidth:"none"}}>
          {SECS.map((s,i)=>(
            <button key={i} onClick={()=>{setSecIdx(i);setOpenMap({});}}
              style={{border:"none",borderRadius:99,padding:"6px 13px",cursor:"pointer",
                whiteSpace:"nowrap",flexShrink:0,fontFamily:"'Nunito',sans-serif",
                fontWeight:700,fontSize:11.5,transition:"all .15s",
                background:secIdx===i?"#fff":"rgba(255,255,255,.2)",
                color:secIdx===i?col:"rgba(255,255,255,.85)"}}>
              {s.emoji} {s.label}
            </button>
          ))}
        </div>
      </div>
      <div style={{flex:1,overflowY:"auto",padding:"12px 14px 24px"}}>
        {sec.isPractice ? (
          <div>
            <div style={{background:"#F8FAFC",borderRadius:14,padding:"14px 15px",marginBottom:14,
              fontSize:12.5,color:"#475569",lineHeight:1.6,border:"1px solid #E2E8F0"}}>
              Retrouve ici les QCM de l'application correspondant à ce chapitre.
              Lance un thème pour t'entraîner directement !
            </div>
            {sec.practices.map(p=>(
              <button key={p.sub} onClick={()=>onStartPractice&&onStartPractice(p.cat,p.sub)}
                style={{width:"100%",background:"#fff",border:"2px solid #E2E8F0",
                  borderRadius:16,padding:"14px 16px",marginBottom:10,
                  cursor:onStartPractice?"pointer":"default",
                  display:"flex",alignItems:"center",gap:14,textAlign:"left",
                  boxShadow:"0 2px 10px rgba(0,0,0,.06)"}}>
                <span style={{fontSize:26,flexShrink:0}}>{p.emoji}</span>
                <div style={{flex:1}}>
                  <div style={{fontFamily:"'Nunito',sans-serif",fontWeight:800,fontSize:14,color:"#1E293B"}}>{p.label}</div>
                  <div style={{fontSize:11,color:"#94A3B8",marginTop:2}}>Questions · S'entraîner</div>
                </div>
                {onStartPractice&&<span style={{color:"#6366F1",fontWeight:800,fontSize:13}}>Lancer →</span>}
              </button>
            ))}
          </div>
        ) : sec.rules.map((rl,i)=>{
          const k=`${secIdx}_${i}`;
          const expanded=isOpen(k,i===0);
          return (
            <div key={rl.id} style={{background:"#fff",borderRadius:18,marginBottom:10,
              overflow:"hidden",boxShadow:"0 2px 14px rgba(0,0,0,.07)",
              borderLeft:`4px solid ${col}`}}>
              <div onClick={()=>tog(k)} style={{display:"flex",alignItems:"center",gap:10,
                padding:"13px 15px",cursor:"pointer",userSelect:"none"}}>
                <div style={{width:30,height:30,borderRadius:"50%",background:col,
                  color:"#fff",display:"flex",alignItems:"center",justifyContent:"center",
                  fontSize:10,fontWeight:800,flexShrink:0}}>{rl.num}</div>
                <div style={{flex:1,fontSize:14.5,fontWeight:700,color:"#0F172A",lineHeight:1.2}}>{rl.title}{rl.titleTex&&<M tex={rl.titleTex}/>}</div>
                <span style={{color:"#94A3B8",fontSize:11,display:"block",
                  transform:expanded?"rotate(180deg)":"",transition:"transform .2s"}}>▼</span>
              </div>
              {expanded&&(
                <div style={{padding:"0 15px 15px"}}>
                  {rl.isTimeline&&(
                    <div style={{background:sec.light,borderRadius:13,padding:"12px",margin:"8px 0",display:"flex",flexDirection:"column",gap:8}}>
                      <div style={{display:"flex",alignItems:"center",gap:10,background:"rgba(8,145,178,.1)",borderRadius:10,padding:"10px 12px"}}>
                        <span style={{fontSize:18,flexShrink:0}}>⏩</span>
                        <div>
                          <div style={{fontSize:10,fontWeight:800,color:col,textTransform:"uppercase",letterSpacing:.6,marginBottom:3}}>Avancer dans le temps</div>
                          <M tex={r`V_i \times CM = V_f`}/>
                        </div>
                      </div>
                      <div style={{display:"flex",alignItems:"center",gap:10,background:"rgba(124,58,237,.1)",borderRadius:10,padding:"10px 12px"}}>
                        <span style={{fontSize:18,flexShrink:0}}>⏪</span>
                        <div>
                          <div style={{fontSize:10,fontWeight:800,color:"#7C3AED",textTransform:"uppercase",letterSpacing:.6,marginBottom:3}}>Remonter dans le temps</div>
                          <M tex={r`V_f \div CM = V_i`}/>
                        </div>
                      </div>
                    </div>
                  )}
                  {rl.fml&&(
                    <div style={{background:sec.light,borderRadius:13,padding:"14px 12px",
                      margin:"8px 0",textAlign:"center",overflowX:"auto"}}>
                      <M tex={rl.fml}/>
                    </div>
                  )}
                  {(rl.blt||[]).map((b,j)=>(
                    <div key={j} style={{display:"flex",gap:7,padding:"3px 0",fontSize:12.5,color:"#475569",lineHeight:1.4}}>
                      <span style={{color:col,fontWeight:700,flexShrink:0}}>•</span><span>{b}</span>
                    </div>
                  ))}
                  {(rl.bltTex||[]).map((b,j)=>(
                    <div key={j} style={{display:"flex",gap:7,padding:"4px 0",alignItems:"flex-start"}}>
                      <span style={{color:col,fontWeight:700,flexShrink:0,marginTop:2}}>•</span>
                      <span style={{overflowX:"auto",fontSize:13}}><M tex={b}/></span>
                    </div>
                  ))}
                  {(rl.tipTex||rl.tip)&&(
                    <div style={{background:"#FEFCE8",borderRadius:10,padding:"10px 12px",
                      fontSize:12,fontWeight:600,color:"#713F12",
                      borderLeft:"3px solid #EAB308",margin:"10px 0",lineHeight:1.4,overflowX:"auto"}}>
                      {rl.tipTex?<M tex={rl.tipTex}/>:<span>{rl.tip}</span>}</div>
                  )}
                  {rl.ex&&(
                    <div style={{background:"#F8FAFC",borderRadius:12,padding:"12px 13px",
                      marginTop:10,borderLeft:`3px solid ${col}`}}>
                      <div style={{fontSize:10,fontWeight:800,color:col,textTransform:"uppercase",
                        letterSpacing:".7px",marginBottom:5}}>Exemple</div>
                      <div style={{fontSize:12.5,color:"#475569",marginBottom:8,lineHeight:1.4}}>
                        {rl.ex.qTex?<M tex={rl.ex.qTex}/>:<span>{rl.ex.q}</span>}
                      </div>
                      <div style={{textAlign:"center",overflowX:"auto"}}><M tex={rl.ex.a}/></div>
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}


// ── CoursMathCalcul — Calcul numérique (Chapitre 0) ──────────────────────────
function CoursMathCalcul({onBack, onStartPractice}) {
  const [secIdx, setSecIdx] = React.useState(0);
  React.useLayoutEffect(() => { if (COURS_OPEN_PRACTICE) { COURS_OPEN_PRACTICE = false; const _pi = SECS.findIndex(s => s.isPractice); if (_pi >= 0) setSecIdx(_pi); } }, []);
  const [openMap, setOpenMap] = React.useState({});
  const tog = k => setOpenMap(p=>({...p,[k]:p[k]===undefined?false:!p[k]}));
  const isOpen = (k,first) => openMap[k]===undefined?first:openMap[k];
  const tabsRef = React.useRef();
  React.useEffect(()=>{
    if(!tabsRef.current) return;
    const btn=tabsRef.current.children[secIdx];
    if(btn) btn.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});
  },[secIdx]);

  const SECS=[
    { emoji:"🔢", label:"Fractions", color:"#DB2777", light:"#FDF2F8", rules:[
      { id:"f1",num:"1",title:"Simplifier / Comparer",
        fml:r`\dfrac{a}{b}=\dfrac{a\times k}{b\times k} \qquad \dfrac{a}{b}=\dfrac{c}{d}\Leftrightarrow a\times d=b\times c`,
        bltTex:[r`\text{Simplifier : diviser numérateur et dénominateur par leur PGCD}`,r`\text{Produit en croix : }\dfrac{a}{b}=\dfrac{c}{d}\Leftrightarrow ad=bc`],
        tipTex:r`\text{Ne pas confondre simplification et réduction au même dénominateur}`,
        ex:{qTex:r`\text{Simplifier }\tfrac{18}{45}`,a:r`\text{PGCD}(18,45)=9\Rightarrow\dfrac{18}{45}=\dfrac{2}{5}`}},
      { id:"f2",num:"2",title:"Additionner / Soustraire",
        fml:r`\dfrac{a}{b}+\dfrac{c}{d}=\dfrac{a\times d+b\times c}{b\times d}`,
        tipTex:r`\text{Réduire au même dénominateur avant d'additionner les numérateurs}`,
        ex:{qTex:r`\text{Calculer }\tfrac{3}{4}+\tfrac{5}{6}`,a:r`\dfrac{3\times6+4\times5}{24}=\dfrac{38}{24}=\dfrac{19}{12}`}},
      { id:"f3",num:"3",title:"Multiplier / Diviser",
        fml:r`\dfrac{a}{b}\times\dfrac{c}{d}=\dfrac{a\times c}{b\times d}\qquad\dfrac{a}{b}\div\dfrac{c}{d}=\dfrac{a}{b}\times\dfrac{d}{c}`,
        tipTex:r`\text{L'inverse de }\tfrac{a}{b}\text{ est }\tfrac{b}{a}\text{ — ne pas confondre avec l'opposé }-\tfrac{a}{b}`,
        ex:{qTex:r`\text{Calculer }\tfrac{2}{3}\div\tfrac{4}{9}`,a:r`\dfrac{2}{3}\times\dfrac{9}{4}=\dfrac{18}{12}=\dfrac{3}{2}`}},
    ]},
    { emoji:"🔍", label:"Divisibilité", color:"#0891B2", light:"#ECFEFF", rules:[
      { id:"d0",num:"3b",title:"Multiple et diviseur",
        fml:r`a\text{ est multiple de }b\Leftrightarrow\exists k\in\mathbb{Z},\ a=k\times b`,
        bltTex:[
          r`\textbf{Multiple :}\ a\text{ est multiple de }b\text{ s'il existe un entier }k\text{ tel que }a=kb`,
          r`\textbf{Diviseur :}\ b\text{ est diviseur de }a\text{ si }a\text{ est multiple de }b\text{ (on dit aussi « }b\text{ divise }a\text{ »)}`,
          r`\textbf{Pair :}\ n\text{ est pair }\Leftrightarrow n=2k\quad(k\in\mathbb{Z})`,
          r`\textbf{Impair :}\ n\text{ est impair }\Leftrightarrow n=2k+1\quad(k\in\mathbb{Z})`,
        ],
        tipTex:r`12=3\times4\Rightarrow12\text{ est multiple de }3\text{ et de }4\\3\text{ et }4\text{ sont des diviseurs de }12`,
        ex:{qTex:r`\text{24 est-il multiple de 6 ? de 5 ?}`,
            a:r`24=6\times4\ \Rightarrow\ \text{oui}\qquad 24\div5=4{,}8\notin\mathbb{Z}\ \Rightarrow\ \text{non}`}},
      { id:"d1",num:"4",title:"Critères de divisibilité",
        fml:null,
        bltTex:[r`\textbf{Par 2}\text{ : chiffre des unités pair}`,r`\textbf{Par 3}\text{ : somme des chiffres divisible par 3}`,r`\textbf{Par 4}\text{ : 2 derniers chiffres divisibles par 4}`,r`\textbf{Par 5}\text{ : unités = 0 ou 5}`,r`\textbf{Par 9}\text{ : somme des chiffres divisible par 9}`,r`\textbf{Par 10}\text{ : unités = 0}`],
        ex:{qTex:r`76\text{ : divisible par }2\ ?\ 3\ ?\ 4\ ?`,a:r`\text{Unités}=6\ (\text{pair})\Rightarrow\div2\ ✓\quad 7+6=13\ \not\div3\ ✗\quad 76=4\times19\Rightarrow\div4\ ✓`}},
    ]},
    { emoji:"⚡", label:"Puissances", color:"#7C3AED", light:"#F5F3FF", rules:[
      { id:"p1",num:"5",title:"Propriétés des puissances",
        fml:r`a^n\times a^m=a^{n+m}\quad a^n\div a^m=a^{n-m}\quad(a^n)^m=a^{n\times m}`,
        bltTex:[r`(a\times b)^n=a^n\times b^n`,r`a^{-n}=\dfrac{1}{a^n}\quad a^0=1`],
        tipTex:r`a^{-n}\neq-a^n\quad\text{et}\quad(a+b)^n\neq a^n+b^n`,
        ex:{qTex:r`\text{Simplifier }\dfrac{3^1\times3^2}{3^1}`,a:r`3^{1+2-1}=3^2=9`}},
      { id:"p2",num:"6",title:"Notation scientifique",
        fml:r`a\times10^n \quad\text{avec }1\leq a<10,\ n\in\mathbb{Z}`,
        bltTex:[r`n>0\text{ → grand nombre}\qquad n<0\text{ → petit nombre}`],
        ex:{qTex:r`\text{Écrire }0{,}00094\text{ en notation scientifique}`,a:r`9{,}4\times10^{-4}`}},
    ]},
    { emoji:"√", label:"Racines", color:"#059669", light:"#F0FDF4", rules:[
      { id:"r1",num:"7",title:"Définition et carrés parfaits",
        fml:r`(\sqrt{a})^2=a\quad\text{définie pour }a\geq0`,
        bltTex:[r`\sqrt{4}=2\quad\sqrt{9}=3\quad\sqrt{16}=4\quad\sqrt{25}=5\quad\sqrt{36}=6`,r`\sqrt{49}=7\quad\sqrt{64}=8\quad\sqrt{81}=9\quad\sqrt{100}=10\quad\sqrt{121}=11\quad\sqrt{144}=12\quad\sqrt{169}=13`],
        ex:{qTex:r`\text{Calculer }\sqrt{169}`,a:r`13^2=169\Rightarrow\sqrt{169}=13`}},
      { id:"r2",num:"8",title:"Racine et valeur absolue",
        fml:r`\sqrt{a^2}=|a|\quad\begin{cases}=a&\text{si }a\geq0\\=-a&\text{si }a<0\end{cases}`,
        tipTex:r`\sqrt{(-5)^2}=5\ \text{(pas }-5\text{) — la racine carrée est toujours positive}`,
        ex:{qTex:r`\text{Calculer }\sqrt{(-5)^2}`,a:r`\sqrt{(-5)^2}=\sqrt{25}=5=|-5|`}},
      { id:"r3",num:"9",title:"Opérations sur les racines",
        fml:r`\sqrt{a\times b}=\sqrt{a}\times\sqrt{b}\qquad\dfrac{\sqrt{a}}{\sqrt{b}}=\sqrt{\dfrac{a}{b}}`,
        tipTex:r`\text{En général : }\sqrt{a+b}\neq\sqrt{a}+\sqrt{b}`,
        ex:{qTex:r`\text{Simplifier }\sqrt{48}`,a:r`\sqrt{48}=\sqrt{16\times3}=4\sqrt{3}`}},
    ]},
    { emoji:"🏋️", label:"S\'entraîner", color:"#0F172A", light:"#F1F5F9", isPractice:true,
      practices:[
        {sub:"fractions",   label:"Fractions",             emoji:"🔢", cat:"numerique"},
        {sub:"puissances",  label:"Puissances",            emoji:"⚡", cat:"numerique"},
        {sub:"scientifique",label:"Écriture scientifique", emoji:"🔬", cat:"numerique"},
        {sub:"racines_n1", label:"Racines carrées · niveau 1", emoji:"√", cat:"numerique"},
        {sub:"racines_n2", label:"Racines carrées · niveau 2", emoji:"√", cat:"numerique"},
        {sub:"racines_n3", label:"Racines carrées · niveau 3", emoji:"√", cat:"numerique"},
        {sub:"racines_n4", label:"Racines carrées · niveau 4", emoji:"√", cat:"numerique"},
        {sub:"relatifs",    label:"Nombres relatifs",      emoji:"±",  cat:"numerique"},
      ]},
  ];

  const sec=SECS[secIdx]; const col=sec.color;
  return (
    <div style={{display:"flex",flexDirection:"column",height:"100%",background:"var(--am-bg-light)"}}>
      <div style={{background:`linear-gradient(135deg,${col},${col}CC)`,padding:"14px 18px 0",flexShrink:0}}>
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:10}}>
          <button onClick={onBack} style={{background:"rgba(255,255,255,.2)",border:"none",
            cursor:"pointer",color:"#fff",fontSize:14,borderRadius:99,
            width:30,height:30,display:"flex",alignItems:"center",justifyContent:"center"}}>✕</button>
          <div>
            <div style={{fontFamily:"'Nunito',sans-serif",fontWeight:900,fontSize:16,color:"#fff"}}>Calcul numérique</div>
            <div style={{fontSize:10,color:"rgba(255,255,255,.7)"}}>📚 Cours interactif · Chapitre 0</div>
          </div>
        </div>
        <div ref={tabsRef} style={{display:"flex",gap:6,overflowX:"auto",paddingBottom:12,scrollbarWidth:"none"}}>
          {SECS.map((s,i)=>(
            <button key={i} onClick={()=>{setSecIdx(i);setOpenMap({});}}
              style={{border:"none",borderRadius:99,padding:"6px 13px",cursor:"pointer",
                whiteSpace:"nowrap",flexShrink:0,fontFamily:"'Nunito',sans-serif",
                fontWeight:700,fontSize:11.5,transition:"all .15s",
                background:secIdx===i?"#fff":"rgba(255,255,255,.2)",
                color:secIdx===i?col:"rgba(255,255,255,.85)"}}>
              {s.emoji} {s.label}
            </button>
          ))}
        </div>
      </div>
      <div style={{flex:1,overflowY:"auto",padding:"12px 14px 24px"}}>
        {sec.isPractice ? (
          <div>
            <div style={{background:"#F8FAFC",borderRadius:14,padding:"14px 15px",marginBottom:14,
              fontSize:12.5,color:"#475569",lineHeight:1.6,border:"1px solid #E2E8F0"}}>
              Retrouve ici les QCM correspondant à ce chapitre. Lance un thème pour t\'entraîner !
            </div>
            {sec.practices.map(p=>(
              <button key={p.sub} onClick={()=>onStartPractice&&onStartPractice(p.cat,p.sub)}
                style={{width:"100%",background:"#fff",border:"2px solid #E2E8F0",
                  borderRadius:16,padding:"14px 16px",marginBottom:10,
                  cursor:onStartPractice?"pointer":"default",
                  display:"flex",alignItems:"center",gap:14,textAlign:"left",
                  boxShadow:"0 2px 10px rgba(0,0,0,.06)"}}>
                <span style={{fontSize:26,flexShrink:0}}>{p.emoji}</span>
                <div style={{flex:1}}>
                  <div style={{fontFamily:"'Nunito',sans-serif",fontWeight:800,fontSize:14,color:"#1E293B"}}>{p.label}</div>
                  <div style={{fontSize:11,color:"#94A3B8",marginTop:2}}>Questions · S\'entraîner</div>
                </div>
                {onStartPractice&&<span style={{color:"#6366F1",fontWeight:800,fontSize:13}}>Lancer →</span>}
              </button>
            ))}
          </div>
        ) : sec.rules.map((rl,i)=>{
          const k=`${secIdx}_${i}`; const expanded=isOpen(k,i===0);
          return (
            <div key={rl.id} style={{background:"#fff",borderRadius:18,marginBottom:10,
              overflow:"hidden",boxShadow:"0 2px 14px rgba(0,0,0,.07)",borderLeft:`4px solid ${col}`}}>
              <div onClick={()=>tog(k)} style={{display:"flex",alignItems:"center",gap:10,
                padding:"13px 15px",cursor:"pointer",userSelect:"none"}}>
                <div style={{width:30,height:30,borderRadius:"50%",background:col,color:"#fff",
                  display:"flex",alignItems:"center",justifyContent:"center",
                  fontSize:10,fontWeight:800,flexShrink:0}}>{rl.num}</div>
                <div style={{flex:1,fontSize:14.5,fontWeight:700,color:"#0F172A",lineHeight:1.2}}>{rl.title}{rl.titleTex&&<M tex={rl.titleTex}/>}</div>
                <span style={{color:"#94A3B8",fontSize:11,display:"block",
                  transform:expanded?"rotate(180deg)":"",transition:"transform .2s"}}>▼</span>
              </div>
              {expanded&&(
                <div style={{padding:"0 15px 15px"}}>
                  {rl.fml&&<div style={{background:sec.light,borderRadius:13,padding:"14px 12px",
                    margin:"8px 0",textAlign:"center",overflowX:"auto"}}><M tex={rl.fml}/></div>}
                  {rl.svgDiag&&<div style={{margin:"8px 0",overflowX:"auto"}} dangerouslySetInnerHTML={{__html:rl.svgDiag}}/>}
                  {(rl.blt||[]).map((b,j)=>(
                    <div key={j} style={{display:"flex",gap:7,padding:"3px 0",fontSize:12.5,color:"#475569",lineHeight:1.4}}>
                      <span style={{color:col,fontWeight:700,flexShrink:0}}>•</span><span>{b}</span>
                    </div>
                  ))}
                  {(rl.bltTex||[]).map((b,j)=>(
                    <div key={j} style={{display:"flex",gap:7,padding:"4px 0",alignItems:"flex-start"}}>
                      <span style={{color:col,fontWeight:700,flexShrink:0,marginTop:2}}>•</span>
                      <span style={{overflowX:"auto",fontSize:13}}><M tex={b}/></span>
                    </div>
                  ))}
                  {(rl.tipTex||rl.tip)&&<div style={{background:"#FEFCE8",borderRadius:10,padding:"10px 12px",
                    fontSize:12,fontWeight:600,color:"#713F12",
                    borderLeft:"3px solid #EAB308",margin:"10px 0",lineHeight:1.4,overflowX:"auto"}}>
                    {rl.tipTex?<M tex={rl.tipTex}/>:<span>{rl.tip}</span>}
                  </div>}
                  {rl.ex&&(
                    <div style={{background:"#F8FAFC",borderRadius:12,padding:"12px 13px",
                      marginTop:10,borderLeft:`3px solid ${col}`}}>
                      <div style={{fontSize:10,fontWeight:800,color:col,textTransform:"uppercase",
                        letterSpacing:".7px",marginBottom:5}}>Exemple</div>
                      <div style={{fontSize:12.5,color:"#475569",marginBottom:8,lineHeight:1.4}}>
                        {rl.ex.qTex?<M tex={rl.ex.qTex}/>:<span>{rl.ex.q}</span>}
                      </div>
                      <div style={{textAlign:"center",overflowX:"auto"}}><M tex={rl.ex.a}/></div>
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}


// ── CoursMathReels — Chapitre 1 : Manipuler les nombres réels ────────────────
function CoursMathReels({onBack, onStartPractice}) {
  const [secIdx, setSecIdx] = React.useState(0);
  React.useLayoutEffect(() => { if (COURS_OPEN_PRACTICE) { COURS_OPEN_PRACTICE = false; const _pi = SECS.findIndex(s => s.isPractice); if (_pi >= 0) setSecIdx(_pi); } }, []);
  const [openMap, setOpenMap] = React.useState({});
  const tog = k => setOpenMap(p=>({...p,[k]:p[k]===undefined?false:!p[k]}));
  const isOpen = (k,first) => openMap[k]===undefined?first:openMap[k];
  const tabsRef = React.useRef();
  React.useEffect(()=>{
    if(!tabsRef.current) return;
    const btn=tabsRef.current.children[secIdx];
    if(btn) btn.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});
  },[secIdx]);

  const SECS=[
    { emoji:"🔢", label:"Ensembles", color:"#0891B2", light:"#ECFEFF", rules:[
      { id:"e1",num:"1",title:"Les ensembles de nombres",
        fml:r`\mathbb{N}\subset\mathbb{Z}\subset\mathbb{D}\subset\mathbb{Q}\subset\mathbb{R}`,
        bltTex:[r`\mathbb{N}\text{ : entiers naturels }\{0, 1, 2, 3,\ldots\}`,r`\mathbb{Z}\text{ : entiers relatifs }\{\ldots,-2,-1,0,1,2,\ldots\}`,r`\mathbb{D}\text{ : décimaux (fraction }a/10^n\text{)}`,
          r`\mathbb{Q}\text{ : rationnels }\left(\tfrac{a}{b},\ a\text{ et }b\text{ entiers},\ b\neq0\right)`,
          r`\mathbb{R}\text{ : réels = abscisses d'une droite graduée}`,
        ],
        ex:{qTex:r`\text{Classer : }0{,}56\ \cdot\ 3\ \cdot\ \tfrac{3}{4}\ \cdot\ -2\ \cdot\ \sqrt{2}`,
            a:r`0{,}56\in\mathbb{D}\quad 3\in\mathbb{N}\quad \tfrac{3}{4}\in\mathbb{Q}\quad -2\in\mathbb{Z}\quad \sqrt{2}\in\mathbb{R}\setminus\mathbb{Q}`}},
      { id:"e2",num:"2",title:"Nombres rationnels et irrationnels",
        fml:null,
        bltTex:[r`\text{Rationnel : s'écrit }\dfrac{a}{b}\ (b\neq0)\text{, dev. décimal périodique}`,r`\text{Irrationnel : pas de fraction }a/b\text{, dev. infini non périodique}`,
          r`\text{Exemples irrationnels : }\sqrt{2},\ \sqrt{3},\ \pi`,
        ],
        tipTex:r`\dfrac{1}{3}=0{,}333\ldots\text{ (infini non terminant) → rationnel mais }\textbf{pas décimal}`,
        ex:{qTex:r`\sqrt{2}\text{ est-il rationnel ?}`,
            a:r`\text{Non : }\sqrt{2}\approx1{,}41421356\ldots\ \text{(infini non périodique)}\Rightarrow\sqrt{2}\in\mathbb{R}\setminus\mathbb{Q}`}},
    ]},
    { emoji:"[·]", label:"Intervalles", color:"#DB2777", light:"#FDF2F8", rules:[
      { id:"i1",num:"3",title:"Notation des intervalles",
        fml:null,
        bltTex:[r`[a\,;\,b]\text{ : }a\leq x\leq b\text{ (crochets fermés = bornes incluses)}`,r`]a\,;\,b[\text{ : }a<x<b\text{ (crochets ouverts = bornes exclues)}`,r`[a\,;\,b[\text{ : }a\leq x<b\text{ (mixte)}`,
          r`[a\,;\,+\infty[\ :\ x\geq a\quad\text{(toujours ouvert côté infini)}`,
        ],
        tipTex:r`\mathbb{R}\text{ lui-même est l'intervalle }]-\infty\,;\,+\infty[`,
        ex:{qTex:r`\text{Écrire }\{x\in\mathbb{R}\,|\,-2\leq x\leq7\}\text{ en notation intervalle}`,
            a:r`[-2\ ;\ 7]`}},
      { id:"i2",num:"4",title:"Intersection et réunion",
        fml:r`A\cap B\ \text{(et)} \qquad A\cup B\ \text{(ou)}`,
        bltTex:[r`A\cap B\text{ : éléments appartenant à }A\textbf{ ET }\text{à }B`,r`A\cup B\text{ : éléments appartenant à }A\textbf{ OU }\text{à }B`,
          r`\text{Ensemble vide }\varnothing\text{ : }A\cap B=\varnothing\text{ si pas d'élément commun}`,
        ],
        ex:{qTex:r`I=\,]-1\,;\,3]\text{ et }J=[0\,;\,4[`,
            a:r`I\cap J=]0\,;3]\qquad I\cup J=]-1\,;4[`}},
    ]},
    { emoji:"|·|", label:"Distance", color:"#7C3AED", light:"#F5F3FF", rules:[
      { id:"d1",num:"5",title:"Distance entre deux réels",
        fml:r`d(a,b)=|b-a|=|a-b|`,
        bltTex:[r`\text{La distance est toujours positive ou nulle}`,r`|b-a|=b-a\text{ si }b\geq a\quad\text{ou}\quad a-b\text{ si }a\geq b`],
        ex:{qTex:r`\text{Distance entre }-1{,}5\text{ et }4`,
            a:r`|4-(-1{,}5)|=|5{,}5|=5{,}5`}},
      { id:"d2",num:"6",title:"Valeur absolue et intervalles",
        fml:r`|x-a|\leq r \Leftrightarrow x\in[a-r\ ;\ a+r]`,
        bltTex:[r`|x|\text{ est la distance entre }x\text{ et }0`,r`|x-a|\leq r\text{ : }x\text{ est à distance au plus }r\text{ de }a`],
        tipTex:r`\text{Interprétation géométrique : }x\text{ est dans l'intervalle centré en }a\text{ de rayon }r`,
        ex:{qTex:r`\text{Résoudre }|x-5|\leq2`,
            a:r`|x-5|\leq2\Leftrightarrow x\in[5-2\,;\,5+2]=[3\,;\,7]`}},
    ]},
    { emoji:"🏋️", label:"S\'entraîner", color:"#0F172A", light:"#F1F5F9", isPractice:true,
      practices:[
        {sub:"ensembles_nombres", label:"Ensembles de nombres",  emoji:"🔢", cat:"numerique"},
        {sub:"intervalles",       label:"Intervalles",           emoji:"[·]", cat:"numerique"},
      ]},
  ];

  const sec=SECS[secIdx]; const col=sec.color;
  return (
    <div style={{display:"flex",flexDirection:"column",height:"100%",background:"var(--am-bg-light)"}}>
      <div style={{background:`linear-gradient(135deg,${col},${col}CC)`,padding:"14px 18px 0",flexShrink:0}}>
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:10}}>
          <button onClick={onBack} style={{background:"rgba(255,255,255,.2)",border:"none",
            cursor:"pointer",color:"#fff",fontSize:14,borderRadius:99,
            width:30,height:30,display:"flex",alignItems:"center",justifyContent:"center"}}>✕</button>
          <div>
            <div style={{fontFamily:"'Nunito',sans-serif",fontWeight:900,fontSize:16,color:"#fff"}}>Nombres réels</div>
            <div style={{fontSize:10,color:"rgba(255,255,255,.7)"}}>📚 Cours interactif · Chapitre 1</div>
          </div>
        </div>
        <div ref={tabsRef} style={{display:"flex",gap:6,overflowX:"auto",paddingBottom:12,scrollbarWidth:"none"}}>
          {SECS.map((s,i)=>(
            <button key={i} onClick={()=>{setSecIdx(i);setOpenMap({});}}
              style={{border:"none",borderRadius:99,padding:"6px 13px",cursor:"pointer",
                whiteSpace:"nowrap",flexShrink:0,fontFamily:"'Nunito',sans-serif",
                fontWeight:700,fontSize:11.5,transition:"all .15s",
                background:secIdx===i?"#fff":"rgba(255,255,255,.2)",
                color:secIdx===i?col:"rgba(255,255,255,.85)"}}>
              {s.emoji} {s.label}
            </button>
          ))}
        </div>
      </div>
      <div style={{flex:1,overflowY:"auto",padding:"12px 14px 24px"}}>
        {sec.isPractice ? (
          <div>
            <div style={{background:"#F8FAFC",borderRadius:14,padding:"14px 15px",marginBottom:14,
              fontSize:12.5,color:"#475569",lineHeight:1.6,border:"1px solid #E2E8F0"}}>
              Lance un thème pour t\'entraîner directement sur les questions de l\'app !
            </div>
            {sec.practices.map(p=>(
              <button key={p.sub} onClick={()=>onStartPractice&&onStartPractice(p.cat,p.sub)}
                style={{width:"100%",background:"#fff",border:"2px solid #E2E8F0",
                  borderRadius:16,padding:"14px 16px",marginBottom:10,
                  cursor:onStartPractice?"pointer":"default",
                  display:"flex",alignItems:"center",gap:14,textAlign:"left",
                  boxShadow:"0 2px 10px rgba(0,0,0,.06)"}}>
                <span style={{fontSize:26,flexShrink:0}}>{p.emoji}</span>
                <div style={{flex:1}}>
                  <div style={{fontFamily:"'Nunito',sans-serif",fontWeight:800,fontSize:14,color:"#1E293B"}}>{p.label}</div>
                  <div style={{fontSize:11,color:"#94A3B8",marginTop:2}}>Questions · S\'entraîner</div>
                </div>
                {onStartPractice&&<span style={{color:"#6366F1",fontWeight:800,fontSize:13}}>Lancer →</span>}
              </button>
            ))}
          </div>
        ) : sec.rules.map((rl,i)=>{
          const k=`${secIdx}_${i}`; const expanded=isOpen(k,i===0);
          return (
            <div key={rl.id} style={{background:"#fff",borderRadius:18,marginBottom:10,
              overflow:"hidden",boxShadow:"0 2px 14px rgba(0,0,0,.07)",borderLeft:`4px solid ${col}`}}>
              <div onClick={()=>tog(k)} style={{display:"flex",alignItems:"center",gap:10,
                padding:"13px 15px",cursor:"pointer",userSelect:"none"}}>
                <div style={{width:30,height:30,borderRadius:"50%",background:col,color:"#fff",
                  display:"flex",alignItems:"center",justifyContent:"center",
                  fontSize:10,fontWeight:800,flexShrink:0}}>{rl.num}</div>
                <div style={{flex:1,fontSize:14.5,fontWeight:700,color:"#0F172A",lineHeight:1.2}}>{rl.title}{rl.titleTex&&<M tex={rl.titleTex}/>}</div>
                <span style={{color:"#94A3B8",fontSize:11,display:"block",
                  transform:expanded?"rotate(180deg)":"",transition:"transform .2s"}}>▼</span>
              </div>
              {expanded&&(
                <div style={{padding:"0 15px 15px"}}>
                  {rl.fml&&<div style={{background:sec.light,borderRadius:13,padding:"14px 12px",
                    margin:"8px 0",textAlign:"center",overflowX:"auto"}}><M tex={rl.fml}/></div>}
                  {rl.svgDiag&&<div style={{margin:"8px 0",borderRadius:12,overflow:"hidden"}} dangerouslySetInnerHTML={{__html:rl.svgDiag}}/>}
                  {(rl.blt||[]).map((b,j)=>(
                    <div key={j} style={{display:"flex",gap:7,padding:"3px 0",fontSize:12.5,color:"#475569",lineHeight:1.4}}>
                      <span style={{color:col,fontWeight:700,flexShrink:0}}>•</span><span>{b}</span>
                    </div>
                  ))}
                  {(rl.bltTex||[]).map((b,j)=>(
                    <div key={j} style={{display:"flex",gap:7,padding:"4px 0",alignItems:"flex-start"}}>
                      <span style={{color:col,fontWeight:700,flexShrink:0,marginTop:2}}>•</span>
                      <span style={{overflowX:"auto",fontSize:13}}><M tex={b}/></span>
                    </div>
                  ))}
                  {(rl.tipTex||rl.tip)&&<div style={{background:"#FEFCE8",borderRadius:10,padding:"10px 12px",
                    fontSize:12,fontWeight:600,color:"#713F12",
                    borderLeft:"3px solid #EAB308",margin:"10px 0",lineHeight:1.4,overflowX:"auto"}}>
                    {rl.tipTex?<M tex={rl.tipTex}/>:<span>{rl.tip}</span>}
                  </div>}
                  {rl.ex&&(
                    <div style={{background:"#F8FAFC",borderRadius:12,padding:"12px 13px",
                      marginTop:10,borderLeft:`3px solid ${col}`}}>
                      <div style={{fontSize:10,fontWeight:800,color:col,textTransform:"uppercase",
                        letterSpacing:".7px",marginBottom:5}}>Exemple</div>
                      <div style={{fontSize:12.5,color:"#475569",marginBottom:8,lineHeight:1.4}}>
                        {rl.ex.qTex?<M tex={rl.ex.qTex}/>:<span>{rl.ex.q}</span>}
                      </div>
                      <div style={{textAlign:"center",overflowX:"auto"}}><M tex={rl.ex.a}/></div>
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}


// ── CoursMathFonctions — Chapitre 2 : Fonctions affines · Équations · Inéquations ──
function CoursMathFonctions({onBack, onStartPractice}) {
  const [secIdx, setSecIdx] = React.useState(0);
  React.useLayoutEffect(() => { if (COURS_OPEN_PRACTICE) { COURS_OPEN_PRACTICE = false; const _pi = SECS.findIndex(s => s.isPractice); if (_pi >= 0) setSecIdx(_pi); } }, []);
  const [openMap, setOpenMap] = React.useState({});
  const tog = k => setOpenMap(p=>({...p,[k]:p[k]===undefined?false:!p[k]}));
  const isOpen = (k,first) => openMap[k]===undefined?first:openMap[k];
  const tabsRef = React.useRef();
  React.useEffect(()=>{
    if(!tabsRef.current) return;
    const btn=tabsRef.current.children[secIdx];
    if(btn) btn.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});
  },[secIdx]);

  const SECS=[
    { emoji:"📈", label:"Fonctions affines", color:"#EA580C", light:"#FFF7ED", rules:[
      { id:"fa1",num:"1",title:"Équation réduite y = mx + p",
        fml:r`y = m\,x + p`,
        bltTex:[r`m\text{ : coefficient directeur (pente de la droite)}`,r`p\text{ : ordonnée à l'origine (coupe l'axe des }y\text{)}`,r`m>0\text{ → droite croissante}\quad m<0\text{ → droite descendante}`,r`m=0\text{ → droite horizontale (fonction constante)}`],
        tipTex:r`\text{Une droite verticale (parallèle à l'axe des }y\text{) n'est PAS une fonction affine}`,
        ex:{qTex:r`\text{Droite passant par }A(0\,;\,3)\text{ et }B(2\,;\,7)`,
            a:r`p=3\quad m=\dfrac{7-3}{2-0}=2\quad\Rightarrow\quad y=2x+3`}},
      { id:"fa2",num:"2",title:"Taux d'accroissement (coefficient directeur)",
        fml:r`m = \dfrac{y_B - y_A}{x_B - x_A}`,
        bltTex:[r`A(x_A\,;\,y_A)\text{ et }B(x_B\,;\,y_B)\text{ deux points distincts de la droite}`,r`\text{Le résultat est le même quel que soit le choix des deux points}`,r`\text{Se lit graphiquement : }\Delta y/\Delta x`],
        ex:{qTex:r`\text{Points }A(1\,;\,2)\text{ et }B(4\,;\,8)`,
            a:r`m=\dfrac{8-2}{4-1}=\dfrac{6}{3}=2`}},
      { id:"fa3",num:"3",title:"Lecture graphique de m et p",
        fml:null,
        svgDiag:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 280 205" style="width:100%;display:block;border-radius:14px">
  <rect width="280" height="205" rx="14" fill="#EFF6FF" stroke="#BFDBFE" stroke-width="2"/>
  <rect x="40" y="12" width="232" height="175" rx="8" fill="white" stroke="#E2E8F0" stroke-width="1"/>
  <clipPath id="plot"><rect x="40" y="12" width="232" height="175" rx="8"/></clipPath>
  <g clip-path="url(#plot)">
    <g stroke="#F1F5F9" stroke-width="1">
      <line x1="55" y1="12" x2="55" y2="187"/>
      <line x1="90" y1="12" x2="90" y2="187"/>
      <line x1="125" y1="12" x2="125" y2="187"/>
      <line x1="160" y1="12" x2="160" y2="187"/>
      <line x1="195" y1="12" x2="195" y2="187"/>
      <line x1="40" y1="190" x2="272" y2="190"/>
      <line x1="40" y1="155" x2="272" y2="155"/>
      <line x1="40" y1="120" x2="272" y2="120"/>
      <line x1="40" y1="85" x2="272" y2="85"/>
      <line x1="40" y1="50" x2="272" y2="50"/>
      <line x1="40" y1="15" x2="272" y2="15"/>
    </g>
    <line x1="44" y1="155" x2="268" y2="155" stroke="#94A3B8" stroke-width="1.6"/>
    <line x1="90" y1="15" x2="90" y2="185" stroke="#94A3B8" stroke-width="1.6"/>
    <polygon points="267,151 274,155 267,159" fill="#94A3B8"/>
    <polygon points="86,16 90,9 94,16" fill="#94A3B8"/>
    <g font-size="9.5" fill="#94A3B8" font-family="sans-serif" text-anchor="middle">
      <text x="55" y="168">-1</text>
      <text x="125" y="168">1</text>
      <text x="160" y="168">2</text>
      <text x="195" y="168">3</text>
      <text x="274" y="159" font-size="10" fill="#64748B">x</text>
    </g>
    <g font-size="9.5" fill="#94A3B8" font-family="sans-serif" text-anchor="end">
      <text x="82" y="193">-1</text>
      <text x="82" y="123">1</text>
      <text x="82" y="88">2</text>
      <text x="82" y="53">3</text>
      <text x="82" y="18">4</text>
      <text x="84" y="159" font-size="9">O</text>
      <text x="92" y="10" font-size="10" fill="#64748B" text-anchor="start">y</text>
    </g>
    <line x1="72" y1="155" x2="148" y2="6" stroke="#EA580C" stroke-width="2.8" stroke-linecap="round"/>
    <text x="150" y="14" font-size="9" fill="#EA580C" font-family="sans-serif" font-style="italic">y=2x+1</text>
    <line x1="90" y1="157" x2="90" y2="122" stroke="#EA580C" stroke-width="1.8" stroke-dasharray="4,2.5"/>
    <circle cx="90" cy="120" r="5.5" fill="#EA580C" stroke="white" stroke-width="2"/>
    <text x="68" y="125" font-size="13" font-weight="bold" fill="#EA580C" font-family="sans-serif">p</text>
    <line x1="107" y1="85" x2="142" y2="85" stroke="#2563EB" stroke-width="2.4" stroke-dasharray="5,3"/>
    <line x1="142" y1="85" x2="142" y2="15" stroke="#2563EB" stroke-width="2.4" stroke-dasharray="5,3"/>
    <path d="M135,85 L135,92 L142,92" fill="none" stroke="#2563EB" stroke-width="1.6"/>
    <circle cx="107" cy="85" r="5" fill="#2563EB" stroke="white" stroke-width="2"/>
    <circle cx="142" cy="15" r="5" fill="#2563EB" stroke="white" stroke-width="2"/>
    <rect x="113" y="90" width="18" height="13" rx="3" fill="white" fill-opacity="0.95"/>
    <text x="124" y="100" font-size="11" font-weight="bold" fill="#2563EB" text-anchor="middle" font-family="sans-serif">1</text>
    <line x1="149" y1="19" x2="149" y2="81" stroke="#2563EB" stroke-width="1.3"/>
    <polygon points="145,21 149,14 153,21" fill="#2563EB"/>
    <polygon points="145,79 149,86 153,79" fill="#2563EB"/>
    <rect x="153" y="44" width="22" height="13" rx="3" fill="white" fill-opacity="0.95"/>
    <text x="164" y="54" font-size="11" font-weight="bold" fill="#2563EB" text-anchor="middle" font-family="sans-serif">m</text>
  </g>
</svg>`,
        bltTex:[
          r`p\text{ = ordonnée à l'origine : là où la droite coupe l'axe des }y`,r`m\text{ = pente : avancer de 1 vers la droite → monter de }m\text{ vers le haut}`,r`m>0\text{ → droite montante}\qquad m<0\text{ → droite descendante}`,
        ],
        ex:{qTex:r`\text{Sur le graphe ci-dessus : lire }p\text{ et }m`,
            a:r`p=1\ \text{(coupe y en }y=1)\quad m=\dfrac{2}{1}=2\ \text{(monte de 2 pour 1 pas)}`}},
    ]},
    { emoji:"⚖️", label:"Équations", color:"#2563EB", light:"#EFF6FF", rules:[
      { id:"eq1",num:"2",title:"Résoudre une équation du 1er degré",
        fml:null,
        bltTex:[
          r`\text{Toute opération sur un membre → même opération sur l'autre}`,r`\text{① Regrouper les termes en }x\text{ d'un côté}`,r`\text{② Les constantes de l'autre côté}`,r`\text{③ Diviser par le coefficient de }x\text{ (si }\neq0\text{)}`,
        ],
        tipTex:r`\text{Vérifier la solution en la substituant dans l'équation de départ}`,
        ex:{qTex:r`\text{Résoudre }-3x-2=x-14`,
            a:r`-3x-x=-14+2\Rightarrow-4x=-12\Rightarrow x=3`}},
      { id:"eq2",num:"3",title:"Produit nul : A × B = 0",
        fml:r`A \times B = 0 \Leftrightarrow A = 0 \text{ ou } B = 0`,
        bltTex:[
          r`A\times B=0\Leftrightarrow A=0\text{ ou }B=0`,r`\text{Résoudre chaque facteur = 0 séparément}`,
        ],
        tipTex:r`A\times B=2\text{ }\textbf{ne donne PAS}\text{ }A=2\text{ ou }B=2\text{ — règle valable uniquement pour }0`,
        ex:{qTex:r`\text{Résoudre }(5x-2)(x-3)=0`,
            a:r`5x-2=0\Rightarrow x=\dfrac{2}{5}\quad\text{ou}\quad x-3=0\Rightarrow x=3`}},
    ]},
    { emoji:"↔️", label:"Inéquations", color:"#7C3AED", light:"#F5F3FF", rules:[
      { id:"ineq1",num:"4",title:"Résoudre une inéquation du 1er degré",
        fml:null,
        bltTex:[
          r`\text{Même méthode que pour les équations}`,r`\text{Ajouter / soustraire → sens de l'inégalité }\textbf{inchangé}`,r`\text{Multiplier / diviser par un réel }\textbf{positif}\text{ → sens }\textbf{inchangé}`,r`\text{Multiplier / diviser par un réel }\textbf{négatif}\text{ → sens }\textbf{inversé}`,
        ],
        tipTex:r`\text{⚠️ Diviser par un }\textbf{négatif}\text{ : }3x<-6\Rightarrow x>\dfrac{-6}{-2}=3`,
        ex:{qTex:r`\text{Résoudre }3x-4<5x-1`,
            a:r`3x-5x<-1+4\Rightarrow-2x<3\Rightarrow x>-\dfrac{3}{2}`}},
      { id:"ineq2",num:"4b",title:"Lire la solution : ensemble et intervalle",
        fml:null,
        bltTex:[
          r`x>a\text{ → solution : }]a\,;+\infty[`,r`x\geq a\text{ → solution : }[a\,;+\infty[`,r`x<a\text{ → solution : }]-\infty\,;a[`,r`a<x\leq b\text{ → solution : }]a\,;b]`,
        ],
        ex:{qTex:r`\text{Solution de }3x-4<5x-1`,
            a:r`x>-\dfrac{3}{2}\quad\Rightarrow\quad\mathcal{S}=\left]-\dfrac{3}{2}\,;+\infty\right[`}},
    ]},
    { emoji:"🏋️", label:"S\'entraîner", color:"#0F172A", light:"#F1F5F9", isPractice:true,
      practices:[
        {sub:"coeff_directeur_lecture", label:"Lire le coefficient directeur", emoji:"📊", cat:"fonctions"},
        {sub:"coeff_directeur_calcul",  label:"Calculer le coefficient directeur", emoji:"📈", cat:"fonctions"},
        {sub:"eq1",                     label:"Équation 1er degré",            emoji:"⚖️", cat:"litteral"},
        {sub:"produit_nul",             label:"Équation produit nul",          emoji:"✖️", cat:"litteral"},
        {sub:"inequation1",             label:"Inéquation 1er degré",          emoji:"↔️", cat:"litteral"},
      ]},
  ];

  const sec=SECS[secIdx]; const col=sec.color;
  return (
    <div style={{display:"flex",flexDirection:"column",height:"100%",background:"var(--am-bg-light)"}}>
      <div style={{background:`linear-gradient(135deg,${col},${col}CC)`,padding:"14px 18px 0",flexShrink:0}}>
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:10}}>
          <button onClick={onBack} style={{background:"rgba(255,255,255,.2)",border:"none",
            cursor:"pointer",color:"#fff",fontSize:14,borderRadius:99,
            width:30,height:30,display:"flex",alignItems:"center",justifyContent:"center"}}>✕</button>
          <div>
            <div style={{fontFamily:"'Nunito',sans-serif",fontWeight:900,fontSize:16,color:"#fff"}}>Fonctions affines · Équations</div>
            <div style={{fontSize:10,color:"rgba(255,255,255,.7)"}}>📚 Cours interactif · Chapitre 2</div>
          </div>
        </div>
        <div ref={tabsRef} style={{display:"flex",gap:6,overflowX:"auto",paddingBottom:12,scrollbarWidth:"none"}}>
          {SECS.map((s,i)=>(
            <button key={i} onClick={()=>{setSecIdx(i);setOpenMap({});}}
              style={{border:"none",borderRadius:99,padding:"6px 13px",cursor:"pointer",
                whiteSpace:"nowrap",flexShrink:0,fontFamily:"'Nunito',sans-serif",
                fontWeight:700,fontSize:11.5,transition:"all .15s",
                background:secIdx===i?"#fff":"rgba(255,255,255,.2)",
                color:secIdx===i?col:"rgba(255,255,255,.85)"}}>
              {s.emoji} {s.label}
            </button>
          ))}
        </div>
      </div>
      <div style={{flex:1,overflowY:"auto",padding:"12px 14px 24px"}}>
        {sec.isPractice ? (
          <div>
            <div style={{background:"#F8FAFC",borderRadius:14,padding:"14px 15px",marginBottom:14,
              fontSize:12.5,color:"#475569",lineHeight:1.6,border:"1px solid #E2E8F0"}}>
              Lance un thème pour t\'entraîner directement sur les questions de l\'app !
            </div>
            {sec.practices.map(p=>(
              <button key={p.sub} onClick={()=>onStartPractice&&onStartPractice(p.cat,p.sub)}
                style={{width:"100%",background:"#fff",border:"2px solid #E2E8F0",
                  borderRadius:16,padding:"14px 16px",marginBottom:10,
                  cursor:onStartPractice?"pointer":"default",
                  display:"flex",alignItems:"center",gap:14,textAlign:"left",
                  boxShadow:"0 2px 10px rgba(0,0,0,.06)"}}>
                <span style={{fontSize:26,flexShrink:0}}>{p.emoji}</span>
                <div style={{flex:1}}>
                  <div style={{fontFamily:"'Nunito',sans-serif",fontWeight:800,fontSize:14,color:"#1E293B"}}>{p.label}</div>
                  <div style={{fontSize:11,color:"#94A3B8",marginTop:2}}>Questions · S\'entraîner</div>
                </div>
                {onStartPractice&&<span style={{color:"#6366F1",fontWeight:800,fontSize:13}}>Lancer →</span>}
              </button>
            ))}
          </div>
        ) : sec.rules.map((rl,i)=>{
          const k=`${secIdx}_${i}`; const expanded=isOpen(k,i===0);
          return (
            <div key={rl.id} style={{background:"#fff",borderRadius:18,marginBottom:10,
              overflow:"hidden",boxShadow:"0 2px 14px rgba(0,0,0,.07)",borderLeft:`4px solid ${col}`}}>
              <div onClick={()=>tog(k)} style={{display:"flex",alignItems:"center",gap:10,
                padding:"13px 15px",cursor:"pointer",userSelect:"none"}}>
                <div style={{width:30,height:30,borderRadius:"50%",background:col,color:"#fff",
                  display:"flex",alignItems:"center",justifyContent:"center",
                  fontSize:10,fontWeight:800,flexShrink:0}}>{rl.num}</div>
                <div style={{flex:1,fontSize:14.5,fontWeight:700,color:"#0F172A",lineHeight:1.2}}>{rl.title}{rl.titleTex&&<M tex={rl.titleTex}/>}</div>
                <span style={{color:"#94A3B8",fontSize:11,display:"block",
                  transform:expanded?"rotate(180deg)":"",transition:"transform .2s"}}>▼</span>
              </div>
              {expanded&&(
                <div style={{padding:"0 15px 15px"}}>
                  {rl.fml&&<div style={{background:sec.light,borderRadius:13,padding:"14px 12px",
                    margin:"8px 0",textAlign:"center",overflowX:"auto"}}><M tex={rl.fml}/></div>}
                  {rl.svgDiag&&<div style={{margin:"8px 0",borderRadius:12,overflow:"hidden"}} dangerouslySetInnerHTML={{__html:rl.svgDiag}}/>}
                  {(rl.blt||[]).map((b,j)=>(
                    <div key={j} style={{display:"flex",gap:7,padding:"3px 0",fontSize:12.5,color:"#475569",lineHeight:1.4}}>
                      <span style={{color:col,fontWeight:700,flexShrink:0}}>•</span><span>{b}</span>
                    </div>
                  ))}
                  {(rl.bltTex||[]).map((b,j)=>(
                    <div key={j} style={{display:"flex",gap:7,padding:"4px 0",alignItems:"flex-start"}}>
                      <span style={{color:col,fontWeight:700,flexShrink:0,marginTop:2}}>•</span>
                      <span style={{overflowX:"auto",fontSize:13}}><M tex={b}/></span>
                    </div>
                  ))}
                  {(rl.tipTex||rl.tip)&&<div style={{background:"#FEFCE8",borderRadius:10,padding:"10px 12px",
                    fontSize:12,fontWeight:600,color:"#713F12",
                    borderLeft:"3px solid #EAB308",margin:"10px 0",lineHeight:1.4,overflowX:"auto"}}>
                    {rl.tipTex?<M tex={rl.tipTex}/>:<span>{rl.tip}</span>}
                  </div>}
                  {rl.ex&&(
                    <div style={{background:"#F8FAFC",borderRadius:12,padding:"12px 13px",
                      marginTop:10,borderLeft:`3px solid ${col}`}}>
                      <div style={{fontSize:10,fontWeight:800,color:col,textTransform:"uppercase",
                        letterSpacing:".7px",marginBottom:5}}>Exemple</div>
                      <div style={{fontSize:12.5,color:"#475569",marginBottom:8,lineHeight:1.4}}>
                        {rl.ex.qTex?<M tex={rl.ex.qTex}/>:<span>{rl.ex.q}</span>}
                      </div>
                      <div style={{textAlign:"center",overflowX:"auto"}}><M tex={rl.ex.a}/></div>
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}


